    <div class="dhead"><div class="dava" style="background:var(--accent-soft);color:var(--accent-ink)"><i class="fas fa-ticket"></i></div><div><div class="dn">${esc(titulo || 'Reserva')}</div><div class="dm">${esc(sub || '')}</div></div></div>
