/* Facebook: todo llega de Zernio por la EF redes-facebook-zernio (la key no baja al navegador).
   Cada bloque puede faltar (`errores`): el add-on Analytics de Zernio es de pago y se avisa en pantalla. */
let redesFbCuentas = {}, redesFbCuenta = {}, redesFbGen = 0;
const FB_RED = { facebook: { nombre: 'Facebook', icono: 'fa-facebook', seccion: 'Página' }, instagram: { nombre: 'Instagram', icono: 'fa-instagram', seccion: 'Cuenta' }, tiktok: { nombre: 'TikTok', icono: 'fa-tiktok', seccion: 'Cuenta' } };
const redesFbCache = new Map(), REDES_FB_CACHE_MS = 5 * 60 * 1000;
let redesFbPintado = {};
const FB_BLOQUES = { pagina: 'las métricas de la página', seguidores: 'los seguidores', posts: 'las publicaciones', horas: 'los mejores horarios', reacciones: 'las reacciones' };
const FB_TIPOS = { image: 'Foto', photo: 'Foto', video: 'Video', reel: 'Reel', carousel: 'Carrusel', album: 'Álbum', link: 'Enlace', text: 'Texto', texto: 'Texto', story: 'Historia' };
const FB_REACCIONES = [['like', 'Me gusta', '#4a9eff'], ['love', 'Me encanta', '#ff5c8a'], ['care', 'Me importa', '#ffb347'], ['haha', 'Jaja', '#ffd23f'], ['wow', 'Asombro', '#a06bff'], ['sad', 'Tristeza', '#7a8aa0'], ['angry', 'Enojo', '#ff6b4a']];
const FB_DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const fbYmd = dt => `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
const fbNum = v => v == null ? '—' : fmt(Math.round(v));
const fbDec = (v, d = 1) => v.toFixed(d).replace('.', ',');
const fbDuracion = ms => ms == null ? '—' : ms >= 3600000 ? fmt(Math.round(ms / 3600000)) + ' h' : fmt(Math.round(ms / 60000)) + ' min';
const fbHttps = u => /^https:\/\//i.test(u || '') ? u : '';
const fbAviso = (ic, msg) => `<div class="recordatorios-banner" style="display:flex;margin:0 0 8px"><i class="fas ${ic}"></i><span>${msg}</span></div>`;
async function redesFbInvocar(body) {
  const { data, error } = await sb.functions.invoke('redes-facebook-zernio', { body });
  if (error || !data?.ok) throw new Error(data?.error || error?.message || 'error');
  return data;
}
function fbPintarCuentas(plat) {
  const box = document.getElementById('redes-fb-cuentas'), cs = redesFbCuentas[plat] || [];
  box.style.display = cs.length > 1 ? '' : 'none';
  box.innerHTML = cs.map(c => `<button class="seg${c.id === redesFbCuenta[plat] ? ' on' : ''}" data-id="${esc(c.id)}">${esc(c.nombre)}</button>`).join('');
  box.querySelectorAll('.seg').forEach(b => b.onclick = () => { redesFbCuenta[plat] = b.dataset.id; fbPintarCuentas(plat); loadRedesZernio(plat); });
}
// Facebook, Instagram y TikTok comparten panel. Con rol marketing (la EF es solo admin)
// Instagram y TikTok caen a sus paneles de siempre, alimentados desde Supabase.
function redesPanelesVista(zernio) {
  document.getElementById('redes-ig-panel').style.display = !zernio && redesRed === 'instagram' ? '' : 'none';
  document.getElementById('redes-tiktok-panel').style.display = !zernio && redesRed === 'tiktok' ? '' : 'none';
  document.getElementById('redes-fb-panel').style.display = zernio ? '' : 'none';
}
const loadRedesFacebook = () => loadRedesZernio('facebook');
async function loadRedesZernio(plat) {
  await ensureChart();
  const R = FB_RED[plat], gen = ++redesFbGen, avisos = document.getElementById('redes-fb-avisos');
  redesPanelesVista(true);
  document.getElementById('redes-fb-seccion').innerHTML = `<i class="fa-brands ${R.icono}"></i> ${R.seccion}`;
  document.getElementById('redes-fb-card-reac').style.display = plat === 'facebook' ? '' : 'none';
  avisos.innerHTML = fbAviso('fa-spinner fa-spin', `Cargando métricas de ${R.nombre} desde Zernio...`);
  try {
    if (!redesFbCuentas[plat]) {
      redesFbCuentas[plat] = (await redesFbInvocar({ accion: 'cuentas', plataforma: plat })).cuentas.filter(c => c.activo);
      redesFbCuenta[plat] = redesFbCuentas[plat][0]?.id || null;
    }
    fbPintarCuentas(plat);
    if (!redesFbCuenta[plat]) { avisos.innerHTML = fbAviso('fa-circle-info', `No hay cuentas de ${R.nombre} conectadas en Zernio.`); return; }
    const [d, h] = periodo(redesPeriodo), fin = addD(h, -1), hoy = new Date();
    const desde = fbYmd(d), hasta = fbYmd(fin > hoy ? hoy : fin), clave = `${plat}|${redesFbCuenta[plat]}|${desde}|${hasta}`;
    let hit = redesFbCache.get(clave);
    if (!hit || Date.now() - hit.t > REDES_FB_CACHE_MS) {
      hit = { t: Date.now(), data: await redesFbInvocar({ accion: 'resumen', plataforma: plat, accountId: redesFbCuenta[plat], desde, hasta }) };
      redesFbCache.set(clave, hit);
    }
    // Si la persona ya se fue de Redes, no se rearman los ~8 gráficos en otra pantalla
    // (~300ms en un celular): la próxima visita recarga y pega en redesFbCache.
    // Volver con el mismo resumen en caché (y el mismo tema) no recrea los gráficos: solo repone los avisos.
    const tema = [...document.documentElement.attributes].map(a => a.name + '=' + a.value).join('|');
    if (gen !== redesFbGen) return;
    if (currentSec !== 'redes') delete ULTIMA_CARGA.redes;
    else if (redesFbPintado.data === hit.data && redesFbPintado.tema === tema) avisos.innerHTML = redesFbPintado.avisos;
    else { fbPintar(hit.data, plat); redesFbPintado = { data: hit.data, tema, avisos: avisos.innerHTML }; }
  } catch (e) {
    console.error(e);
    if (gen !== redesFbGen) return;
    if (plat !== 'facebook') { redesPanelesVista(false); plat === 'tiktok' ? loadRedesTikTok() : loadRedes(); return; }
    avisos.innerHTML = fbAviso('fa-triangle-exclamation', `No se pudieron cargar las métricas de ${R.nombre}. Intenta de nuevo en un momento.`);
    errToast(`No se pudieron cargar las métricas de ${R.nombre}`);
  }
}
function fbLinea(id, serie, etiqueta, color, vacio, desdeCero = true) {
  const s = serie || [];
  mk(id, { type: 'line', data: { labels: s.map(x => x.dia.slice(8) + '/' + x.dia.slice(5, 7)), datasets: [{ label: etiqueta, data: s.map(x => x.v), borderColor: color, backgroundColor: color + '1a', fill: true, tension: .35, borderWidth: 2, pointRadius: 0 }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { display: false }, ticks: { maxTicksLimit: 10 } }, y: { grid: { color: gridColor() }, beginAtZero: desdeCero } } } });
  chartVacio(id, s.length > 0 && (!desdeCero || s.some(x => x.v > 0)), vacio);
}
function fbBarras(id, etiquetas, datos, colores, vacio, horizontal = true) {
  mk(id, { type: 'bar', data: { labels: etiquetas, datasets: [{ data: datos, backgroundColor: colores, borderRadius: 6, barThickness: horizontal ? 18 : undefined, maxBarThickness: 34 }] }, options: { indexAxis: horizontal ? 'y' : 'x', responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { color: horizontal ? gridColor() : 'transparent' }, beginAtZero: true }, y: { grid: { color: horizontal ? 'transparent' : gridColor() }, beginAtZero: true } } } });
  chartVacio(id, datos.some(v => v > 0), vacio);
}
const FB_METRICAS_ETIQ = { reach: 'Alcance', views: 'Vistas', accounts_engaged: 'Cuentas que interactuaron', total_interactions: 'Interacciones', profile_views: 'Visitas al perfil', likes_count: 'Me gusta totales', video_count: 'Videos', video_views: 'Reproducciones', impressions: 'Impresiones', likes: 'Me gusta', comments: 'Comentarios', shares: 'Compartidos' };
const fbEtiqueta = k => FB_METRICAS_ETIQ[k] || k.replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());
const FB_ICONOS = ['fa-eye', 'fa-arrow-pointer', 'fa-heart', 'fa-circle-play', 'fa-hand-pointer', 'fa-chart-simple'];
const FB_COLORES = ['var(--accent)', 'var(--purple)', '#ff5c8a', '#34d399', '#ffb347', 'var(--blue)'];
function fbPintar(data, plat = 'facebook') {
  const e = data.errores || {}, pg = data.pagina, sg = data.seguidores, ps = data.posts, rc = data.reacciones, hr = data.horas;
  const sin = (k, normal) => !e[k] ? normal : e[k].motivo === 'addon' ? 'Requiere el add-on Analytics de Zernio.' : 'No se pudo cargar este bloque.';
  const avisos = [], conAddon = Object.keys(e).filter(k => e[k].motivo === 'addon'), conError = Object.keys(e).filter(k => e[k].motivo !== 'addon');
  if (conAddon.length) avisos.push(fbAviso('fa-lock', `Zernio no entrega ${conAddon.map(k => FB_BLOQUES[k] || k).join(', ')} sin el <b>add-on Analytics</b>. Actívalo en Zernio (tiene costo) y aparecerán aquí.`));
  if (conError.length) avisos.push(fbAviso('fa-triangle-exclamation', `No se pudo cargar ${conError.map(k => `${FB_BLOQUES[k] || k}${e[k].estado ? ' (error ' + e[k].estado + (e[k].detalle ? ': ' + esc(e[k].detalle) : '') + ')' : ''}`).join(', ')}.`));
  if (data.rango?.insights_recortado) avisos.push(fbAviso('fa-circle-info', `Meta limita las métricas de la cuenta a ${data.rango.insights_max_dias || 88} días: se muestra del ${fmtFechaSolo(data.rango.insights_desde)} al ${fmtFechaSolo(data.rango.hasta)}.`));
  if (pg?.retraso) avisos.push(fbAviso('fa-clock', `Meta publica las métricas de la página con retraso (${esc(pg.retraso)}).`));
  document.getElementById('redes-fb-avisos').innerHTML = avisos.join('');

  const t = pg?.totales, serie = pg?.series || {};
  const crec = sg ? `${sg.crecimiento > 0 ? '+' : ''}${fbNum(sg.crecimiento)} (${fbDec(sg.porcentaje || 0)}%) en el período` : null;
  // Meta no entrega ganados/perdidos por día: si la métrica viene vacía se derivan de la serie de seguidores.
  const gp = sg?.ganados_perdidos || [];
  const ganDer = gp.map(x => ({ dia: x.dia, v: x.ganados })), perDer = gp.map(x => ({ dia: x.dia, v: x.perdidos }));
  const gan = serie.followers_gained?.some(x => x.v > 0) ? serie.followers_gained : ganDer;
  const per = serie.followers_lost?.some(x => x.v > 0) ? serie.followers_lost : perDer;
  const sum = xs => xs.reduce((a, x) => a + x.v, 0);
  const kpiSeg = [
    { t: 'Seguidores', v: fbNum(sg?.actual ?? t?.page_follows), d: crec, i: 'fa-users', c: 'var(--blue)' },
    { t: 'Seguidores ganados', v: fbNum(gan.length ? sum(gan) : t?.followers_gained), i: 'fa-user-plus', c: '#34d399' },
    { t: 'Seguidores perdidos', v: fbNum(per.length ? sum(per) : t?.followers_lost), i: 'fa-user-minus', c: '#ff6b6b' },
  ];
  const kpiPlat = plat === 'facebook' ? [
    { t: 'Vistas de contenido', v: fbNum(t?.page_media_view), i: 'fa-eye', c: 'var(--accent)' },
    { t: 'Visitas a la página', v: fbNum(t?.page_views_total), i: 'fa-arrow-pointer', c: 'var(--purple)' },
    { t: 'Interacciones', v: fbNum(t?.page_post_engagements), i: 'fa-heart', c: '#ff5c8a' },
    { t: 'Reproducciones de video', v: fbNum(t?.page_video_views), i: 'fa-circle-play', c: '#34d399' },
    { t: 'Tiempo de video', v: fbDuracion(t?.page_video_view_time), i: 'fa-hourglass-half', c: '#ffb347' },
  ] : Object.keys(t || {}).filter(k => !/follow|gained|lost/i.test(k) || /views/.test(k)).slice(0, 6)
    .map((k, i) => ({ t: fbEtiqueta(k), v: fbNum(t[k]), i: FB_ICONOS[i % 6], c: FB_COLORES[i % 6] }));
  pintarKPIs('redes-fb-kpis-pagina', [...kpiSeg, ...kpiPlat]);
  const segSerie = sg?.serie?.length ? sg.serie : serie.page_follows;
  fbLinea('chFbSeguidores', segSerie, 'Seguidores', '#4a9eff', sin('seguidores', 'Sin datos de seguidores en este período.'), false);
  const dias = [...new Set([...gan, ...per].map(x => x.dia))].sort();
  mk('chFbGanPer', { type: 'bar', data: { labels: dias.map(d => d.slice(8) + '/' + d.slice(5, 7)), datasets: [
    { label: 'Ganados', data: dias.map(d => gan.find(x => x.dia === d)?.v || 0), backgroundColor: '#34d399', borderRadius: 4, maxBarThickness: 14 },
    { label: 'Perdidos', data: dias.map(d => per.find(x => x.dia === d)?.v || 0), backgroundColor: '#ff6b6b', borderRadius: 4, maxBarThickness: 14 },
  ] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: true, labels: { boxWidth: 10 } } }, scales: { x: { grid: { display: false }, ticks: { maxTicksLimit: 10 } }, y: { grid: { color: gridColor() }, beginAtZero: true } } } });
  chartVacio('chFbGanPer', dias.length > 0 && [...gan, ...per].some(x => x.v > 0), sin('pagina', 'Sin movimiento de seguidores en este período.'));
  const pd2 = ps?.por_dia || [], nfb = plat === 'facebook';
  const alc = serie.reach?.length ? serie.reach : pd2.map(x => ({ dia: x.dia, v: x.alcance }));
  const t1 = nfb ? ['Vistas de contenido', 'Diarias, de toda la página'] : serie.reach?.length ? ['Alcance de la cuenta', 'Diario, de toda la cuenta'] : ['Alcance por publicación', 'Suma por día de publicación'];
  document.getElementById('redes-fb-t1').textContent = t1[0]; document.getElementById('redes-fb-s1').textContent = t1[1];
  document.getElementById('redes-fb-t2').textContent = nfb ? 'Interacciones con publicaciones' : 'Interacciones por publicación';
  document.getElementById('redes-fb-s2').textContent = nfb ? 'Diarias, de toda la página' : 'Suma por día de publicación';
  fbLinea('chFbVistas', nfb ? serie.page_media_view : alc, 'Alcance', '#4a9eff', sin(nfb ? 'pagina' : 'posts', 'Sin datos en este período.'));
  fbLinea('chFbInter', nfb ? serie.page_post_engagements : pd2.map(x => ({ dia: x.dia, v: x.interacciones })), 'Interacciones', '#ff5c8a', sin(nfb ? 'pagina' : 'posts', 'Sin datos en este período.'));

  const tp = ps?.totales, base = tp ? (tp.alcance || tp.impresiones || tp.vistas) : 0;
  pintarKPIs('redes-fb-kpis-posts', [
    { t: 'Publicaciones', v: fbNum(tp?.publicaciones), i: 'fa-images', c: 'var(--blue)' },
    { t: 'Impresiones', v: fbNum(tp?.impresiones), i: 'fa-chart-simple', c: 'var(--purple)' },
    { t: 'Alcance', v: fbNum(tp?.alcance), i: 'fa-eye', c: 'var(--accent)' },
    { t: 'Vistas de video', v: fbNum(tp?.vistas), i: 'fa-circle-play', c: '#34d399' },
    { t: 'Clics', v: fbNum(tp?.clics), i: 'fa-hand-pointer', c: '#ffb347' },
    { t: 'Me gusta', v: fbNum(tp?.likes), i: 'fa-thumbs-up', c: '#4a9eff' },
    { t: 'Comentarios', v: fbNum(tp?.comentarios), i: 'fa-comment', c: 'var(--purple)' },
    { t: 'Compartidos', v: fbNum(tp?.compartidos), i: 'fa-share', c: '#34d399' },
    { t: 'Interacciones', v: fbNum(tp?.interacciones), i: 'fa-heart', c: '#ff5c8a' },
    { t: 'Tasa de interacción', v: tp && base ? fbDec(tp.interacciones / base * 100) + '%' : '—', i: 'fa-percent', c: 'var(--accent)' },
  ]);
  const tipos = ps?.por_tipo || [];
  fbBarras('chFbTipo', tipos.map(x => FB_TIPOS[x.tipo] || x.tipo), tipos.map(x => x.publicaciones), '#a06bff', sin('posts', 'Sin publicaciones en este período.'));
  const reac = rc?.total || {};
  fbBarras('chFbReacciones', FB_REACCIONES.map(r => r[1]), FB_REACCIONES.map(r => reac[r[0]] || 0), FB_REACCIONES.map(r => r[2]), sin('reacciones', 'Sin reacciones en los mejores posts.'));
  const orden = [1, 2, 3, 4, 5, 6, 0], pd = hr?.por_dia || [];
  fbBarras('chFbDia', orden.map(d => FB_DIAS[d]), orden.map(d => +(pd.find(x => x.dia === d)?.engagement || 0).toFixed(1)), '#4a9eff', sin('horas', 'Aún no hay suficientes publicaciones para calcularlo.'), false);
  document.getElementById('redes-fb-horas').innerHTML = hr?.mejores?.length
    ? `<div style="display:flex;flex-direction:column;gap:10px">${hr.mejores.map((s, i) => `<div style="display:flex;align-items:center;gap:10px"><span class="bt-tag" style="--c:var(--accent)">${i + 1}</span><b>${FB_DIAS[s.dia]} ${String(s.hora).padStart(2, '0')}:00</b><span style="margin-left:auto;color:var(--muted);font-size:12.5px">${fbDec(s.engagement)} interacciones · ${fmt(s.publicaciones)} pub.</span></div>`).join('')}</div>`
    : `<div class="lt-vacio"><i class="fas fa-inbox"></i> ${sin('horas', 'Aún no hay suficientes publicaciones para calcularlo.')}</div>`;

  const top = ps?.top || [];
  document.getElementById('redes-fb-top-body').innerHTML = top.length ? top.map((p, i) => {
    const r = rc?.por_post?.[p.idPlataforma], url = fbHttps(p.url), mini = fbHttps(p.miniatura);
    const tasa = p.alcance || p.impresiones || p.vistas;
    const chips = r ? FB_REACCIONES.filter(x => r[x[0]] > 0).map(x => `<span class="bt-tag" style="--c:${x[2]}">${x[1]} ${fmt(r[x[0]])}</span>`).join('') : '';
    return `<article class="lt-card" style="--i:${Math.min(i, 20)}">
      <div class="tt-row">
        ${mini ? `<img class="tt-thumb" style="width:62px;height:62px" src="${esc(mini)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'">` : ''}
        <div class="tt-title" title="${esc(p.texto)}">${esc(p.texto || 'Sin texto')}</div>
        <span class="bt-tag" style="--c:var(--accent)">${esc(FB_TIPOS[p.tipo] || p.tipo)}</span>
      </div>
      <div class="lt-cifras">
        <div><span>Alcance</span><b>${fbNum(p.alcance)}</b></div>
        <div><span>Impresiones</span><b>${fbNum(p.impresiones)}</b></div>
        <div><span>Vistas</span><b>${fbNum(p.vistas)}</b></div>
        <div><span>Me gusta</span><b>${fbNum(p.likes)}</b></div>
        <div><span>Comentarios</span><b>${fbNum(p.comentarios)}</b></div>
        <div><span>Compartidos</span><b>${fbNum(p.compartidos)}</b></div>
        <div><span>Clics</span><b>${fbNum(p.clics)}</b></div>
        <div><span>Interacciones</span><b>${fbNum(p.interacciones)}</b></div>
        <div><span>Tasa</span><b>${tasa > 0 ? fbDec(p.interacciones / tasa * 100) + '%' : '—'}</b></div>
      </div>
      ${chips ? `<div class="lt-card-pie">${chips}</div>` : ''}
      <div class="lt-card-pie">
        ${p.fecha ? `<span class="csub" style="margin:0 auto 0 0">${esc(fmtFechaSolo(p.fecha.slice(0, 10)))}</span>` : ''}
        ${url ? `<a class="btn-sm lt-primario" href="${esc(url)}" target="_blank" rel="noopener"><i class="fa-brands ${FB_RED[plat].icono}"></i> Ver publicación</a>` : ''}
      </div>
    </article>`;
  }).join('') : `<div class="lt-vacio"><i class="fas fa-inbox"></i> ${sin('posts', 'Sin publicaciones en este período')}</div>`;
}
async function enviarChatRedes() {
  const input = document.getElementById('redes-chat-input'), btn = document.getElementById('redes-chat-send');
  const texto = input.value.trim();
  if (!texto || btn.disabled) return;
  addChatBubbleRedes('user', texto);
  redesChatHistory.push({ role: 'user', content: texto });
  input.value = ''; input.style.height = 'auto';
  btn.disabled = true;
  const loadingEl = addChatBubbleRedes('bot', 'Pensando...', true);
  const [d, h] = periodo(redesPeriodo);
  const { data, error } = await sb.functions.invoke('redes-analista-chat', { body: { messages: redesChatHistory, periodo: { desde: iso(d), hasta: iso(h) } } });
  loadingEl.remove();
  btn.disabled = false;
  if (error || !data?.respuesta) { addChatBubbleRedes('bot', 'No pude conectar con el analista, intenta de nuevo en un momento.'); return; }
  addChatBubbleRedes('bot', data.respuesta);
  redesChatHistory.push({ role: 'assistant', content: data.respuesta });
}
function addChatBubbleRedes(who, texto, loading) {
  const log = document.getElementById('redes-chat-log');
  const div = document.createElement('div');
  div.className = `chat-msg ${who}${loading ? ' loading' : ''}`;
  if (who === 'bot' && !loading) div.innerHTML = renderBotText(texto);
  else div.textContent = texto;
  let el = div;
  if (who === 'bot') {
    const row = document.createElement('div');
    row.className = 'chat-row';
    row.innerHTML = '<span class="chat-avatar"><i class="fa-brands fa-instagram"></i></span>';
    row.appendChild(div);
    log.appendChild(row);
    el = row;
  } else {
    log.appendChild(div);
  }
  log.scrollTop = log.scrollHeight;
  return el;
}

/* ---------- Consultor IA (2026-08-11) ----------------------------------
   Chat de solo consulta contra crm-consultor-chat: arquitectura/decisiones
   (CLAUDE.md, HANDOFFs, memoria de Claude) + estado operativo en vivo
   (leads de hoy, pendientes de timeout, última corrida de cada cron). Nunca
   edita ni ejecuta nada -- para eso está Claude Code, ver aviso en el propio
   HTML de la sección. Mismo patrón de chat que Redes (enviarChatRedes),
   reusando las mismas clases CSS (chat-wrap/chat-log/chat-inputbar). */
let consultorChatHistory = [];
function setupConsultorIA() {
  const input = document.getElementById('consultor-chat-input');
  document.getElementById('consultor-chat-send').onclick = enviarChatConsultor;
  input.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); enviarChatConsultor(); } });
  input.addEventListener('input', () => { input.style.height = 'auto'; input.style.height = Math.min(input.scrollHeight, 120) + 'px'; });
  if (!consultorChatHistory.length) {
    addChatBubbleConsultor('bot', 'Hola, soy el consultor técnico del proyecto. Preguntame cómo está armado algo, qué se decidió y por qué, o cómo va el CRM ahora mismo (leads de hoy, quién va atrasado).');
  }
}
async function enviarChatConsultor() {
  const input = document.getElementById('consultor-chat-input'), btn = document.getElementById('consultor-chat-send');
  const texto = input.value.trim();
  if (!texto || btn.disabled) return;
  addChatBubbleConsultor('user', texto);
  consultorChatHistory.push({ role: 'user', content: texto });
  input.value = ''; input.style.height = 'auto';
  btn.disabled = true;
  const loadingEl = addChatBubbleConsultor('bot', 'Pensando...', true);
  const { data, error } = await sb.functions.invoke('crm-consultor-chat', { body: { messages: consultorChatHistory } });
  loadingEl.remove();
  btn.disabled = false;
  if (error || !data?.respuesta) { addChatBubbleConsultor('bot', 'No pude conectar con el consultor, intenta de nuevo en un momento.'); return; }
  addChatBubbleConsultor('bot', data.respuesta);
  consultorChatHistory.push({ role: 'assistant', content: data.respuesta });
}
function addChatBubbleConsultor(who, texto, loading) {
  const log = document.getElementById('consultor-chat-log');
  const div = document.createElement('div');
  div.className = `chat-msg ${who}${loading ? ' loading' : ''}`;
  if (who === 'bot' && !loading) div.innerHTML = renderBotText(texto);
  else div.textContent = texto;
  let el = div;
  if (who === 'bot') {
    const row = document.createElement('div');
    row.className = 'chat-row';
    row.innerHTML = '<span class="chat-avatar"><i class="fas fa-user-tie"></i></span>';
    row.appendChild(div);
    log.appendChild(row);
    el = row;
  } else {
    log.appendChild(div);
  }
  log.scrollTop = log.scrollHeight;
  return el;
}

/* ---------- Asistente administrativo (2026-09-25, Etapa C3) ----------------
   Chat contra la EF asistente-admin, que llama RPCs con el JWT de quien
   escribe (nunca service role), así que ve y toca lo mismo que el usuario.
   El código de /vincular une el chat privado de Telegram con este usuario.
   Deshacer pasa por la EF (asistente_acciones solo la escribe ella).
   Desde 2026-09-26 el chat vive en Lyra (más abajo); esta sección queda para
   el vínculo con Telegram y el historial de acciones. */
let asisChatHistory = [];
const ASIS_ERRORES = {
  asistente_apagado: 'Estoy apagada por ahora. Alguien me desenchufó; vuelvo pronto.',
  no_autorizado: 'Tu usuario no tiene acceso a Lyra.',
  no_deshacible: 'Esa acción ya no se puede deshacer.',
  voz_fallo: 'Se me fue la voz esta vez. El texto sigue arriba, intacto.',
  accion_no_existe: 'No encontré esa acción.',
  adjunto_invalido: 'Ese adjunto no me llegó bien. Súbelo otra vez, porfa.',
  adjunto_muy_grande: 'Ese archivo pasa de 10 MB. Mi límite es ese, no es personal.',
  adjunto_no_disponible: 'No pude abrir el adjunto. Prueba subirlo de nuevo.',
  sin_transcripcion: 'Hoy no puedo escuchar audios. ¿Me lo escribes?',
  no_se_pudo_transcribir: 'No logré entender el audio. ¿Lo repites o me lo escribes?',
  adjunto_no_subido: 'No pude subir el archivo. Revisa la conexión y prueba otra vez.',
  adjunto_pesado: 'Ese archivo pasa de 10 MB, no lo puedo recibir.',
  max_adjuntos: 'Máximo 3 archivos por mensaje. Manda estos y seguimos.',
  audio_corto: 'Eso fue más corto que un suspiro. Mantén grabando y habla.',
  sin_microfono: 'No encuentro un micrófono en este equipo.',
  audio_mudo: 'No te escuché nada: el micrófono llegó en silencio. Revisa cuál está elegido en el candado de la barra de direcciones o si está silenciado.',
  microfono_denegado: 'Necesito permiso para usar el micrófono. Actívalo en el candado de la barra de direcciones.',
  escucha_no_disponible: 'No pude activar la escucha en este navegador. Sigo por escrito.',
};
const ASIS_HERRAMIENTAS = {
  guardar_servicio: ['fa-suitcase', 'Servicio guardado'], guardar_pasajero: ['fa-user-plus', 'Pasajero guardado'],
  nota_reserva: ['fa-note-sticky', 'Nota en la reserva'], correo_proveedor: ['fa-envelope', 'Correo a proveedor'],
  adjuntar_documento: ['fa-paperclip', 'Documento adjunto'], asignar_proveedor_reserva: ['fa-handshake', 'Proveedor de la reserva'],
  correo_empresa: ['fa-building', 'Correo a empresa'], asignar_empresa_reserva: ['fa-building-circle-check', 'Empresa de la reserva'], deshacer_accion: ['fa-rotate-left', 'Acción deshecha'],
  mover_etapa_lead: ['fa-arrow-right-arrow-left', 'Etapa del lead'], nota_lead: ['fa-note-sticky', 'Nota del lead'],
  reasignar_lead: ['fa-user-check', 'Lead reasignado'], registrar_contacto_lead: ['fa-phone', 'Contacto registrado'],
  declarar_pago: ['fa-money-bill-wave', 'Pago declarado'], verificar_pago: ['fa-check-double', 'Pago verificado'],
  editar_tarifa: ['fa-tag', 'Tarifa editada'], crear_tarifa: ['fa-tag', 'Tarifa creada'],
  retirar_tarifa: ['fa-tag', 'Tarifa retirada'], corregir_precio_tarifario: ['fa-tag', 'Precio corregido'],
};
function setupAsistente() {
  document.getElementById('asis-abrir-lyra').onclick = () => lyraAbrir();
  document.getElementById('asis-codigo-btn').onclick = generarCodigoAsistente;
  document.getElementById('asis-acc-recargar').onclick = cargarAccionesAsistente;
  document.getElementById('asis-acc-lista').addEventListener('click', e => {
    const b = e.target.closest('[data-asis-deshacer]');
    if (b) deshacerAccionAsistente(Number(b.dataset.asisDeshacer), b);
  });
  setupMemoriaLyra();
}
function loadAsistente() { cargarVinculoAsistente(); cargarAccionesAsistente(); cargarMemoriaLyra(); }
async function cargarVinculoAsistente() {
  const box = document.getElementById('asis-vinc');
  const { data, error } = await sb.rpc('asistente_mi_vinculo');
  if (error) { box.textContent = 'No se pudo consultar el vínculo con Telegram.'; return; }
  box.innerHTML = data?.vinculado
    ? `<span><i class="fas fa-circle-check" style="color:var(--green)"></i> Tu Telegram está vinculado desde el <b>${esc(new Date(data.vinculado_en).toLocaleDateString('es-VE'))}</b>. Escribile al bot por privado.</span>`
    : '<span>Para usarlo desde Telegram: tocá <b>Generar código</b> y mandale al bot, por privado, <b>/vincular CÓDIGO</b>. El código vence en 10 minutos.</span>';
}
async function generarCodigoAsistente() {
  const btn = document.getElementById('asis-codigo-btn'), box = document.getElementById('asis-vinc');
  btn.disabled = true;
  const { data, error } = await sb.rpc('asistente_generar_codigo');
  btn.disabled = false;
  if (error || !data?.codigo) { box.textContent = 'No se pudo generar el código, probá de nuevo.'; return; }
  box.innerHTML = `<span class="asis-codigo">${esc(data.codigo)}</span><span>Mandale al bot, por privado: <b>/vincular ${esc(data.codigo)}</b> · vence a las ${esc(new Date(data.expira_en).toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit' }))}</span>`;
}
async function cargarAccionesAsistente() {
  const cont = document.getElementById('asis-acc-lista');
  const { data, error } = await sb.rpc('asistente_acciones_listar', { p_limite: 50 });
  if (error) { cont.innerHTML = '<div class="csub">No se pudieron cargar las acciones.</div>'; return; }
  const filas = (data || []).filter(a => a.escritura);
  if (!filas.length) { cont.innerHTML = '<div class="csub">Todavía no hay cambios hechos por el asistente.</div>'; return; }
  cont.innerHTML = filas.map(a => {
    const [icono, titulo] = ASIS_HERRAMIENTAS[a.herramienta] || ['fa-gear', a.herramienta];
    const cuando = new Date(a.created_at).toLocaleString('es-VE', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
    const detalle = [a.reserva_id ? `Reserva #${a.reserva_id}` : '', a.canal === 'telegram' ? 'Telegram' : 'CRM', ROL === 'admin' ? a.usuario : '', cuando]
      .filter(Boolean).join(' · ');
    const estado = a.ok === false ? ' · <b>falló</b>' : a.ok === null ? ' · en curso' : a.deshecha_en ? ' · deshecha' : '';
    const boton = a.deshacible && a.ok ? `<button class="btn-sm" type="button" data-asis-deshacer="${a.id}"><i class="fas fa-rotate-left"></i> Deshacer</button>` : '';
    return `<div class="asis-acc${a.deshecha_en ? ' deshecha' : ''}"><span class="asis-acc-i${a.ok === false ? ' err' : ''}"><i class="fas ${icono}"></i></span>`
      + `<div class="asis-acc-b"><b>${esc(titulo)}</b><small>${esc(detalle)}${estado}</small></div>${boton}</div>`;
  }).join('');
}
async function deshacerAccionAsistente(id, btn) {
  if (!Number.isSafeInteger(id)) return;
  const ok = await confirmarSheet({ titulo: '¿Deshacer esta acción?', detalle: 'Se revierte el cambio que hizo el asistente.', textoOk: 'Deshacer', destructivo: true });
  if (!ok) return;
  btn.disabled = true;
  const { data, error } = await sb.functions.invoke('asistente-admin', { body: { deshacer_accion_id: id } });
  if (error || !data?.ok) {
    btn.disabled = false;
    document.getElementById('asis-acc-sub').textContent = ASIS_ERRORES[data?.error] || 'No se pudo deshacer, probá de nuevo.';
    return;
  }
  document.getElementById('asis-acc-sub').textContent = 'Acción deshecha.';
  cargarAccionesAsistente();
}

// Memoria de Lyra: cada uno ve y borra lo suyo; el admin elige usuario y además corrige.
function setupMemoriaLyra() {
  const sel = document.getElementById('asis-mem-usuario'), lista = document.getElementById('asis-mem-lista');
  sel.onchange = cargarMemoriaLyra;
  lista.addEventListener('click', e => {
    const x = e.target.closest('[data-mem-borrar]'), ed = e.target.closest('[data-mem-editar]');
    if (x) borrarMemoriaLyra(Number(x.dataset.memBorrar), x);
    else if (ed) editarMemoriaLyra(ed.closest('.asis-acc'), Number(ed.dataset.memEditar));
  });
}
async function cargarMemoriaLyra() {
  const sel = document.getElementById('asis-mem-usuario'), cont = document.getElementById('asis-mem-lista');
  if (ROL === 'admin' && !sel.options.length) {
    const { data } = await sb.rpc('lyra_memoria_usuarios');
    if (Array.isArray(data) && data.length) {
      sel.innerHTML = data.map(u => `<option value="${esc(u.id)}">${esc(u.nombre || 'Sin nombre')}${u.cuantas ? ` (${u.cuantas})` : ''}</option>`).join('');
      sel.value = MI_USUARIO_ID; sel.hidden = false;
    }
  }
  const otro = ROL === 'admin' && sel.value && sel.value !== MI_USUARIO_ID ? sel.value : null;
  const { data, error } = await sb.rpc('lyra_memoria_listar', otro ? { p_usuario: otro } : {});
  if (error) { cont.innerHTML = '<div class="csub">No se pudo cargar la memoria de Lyra.</div>'; return; }
  if (!data?.length) { cont.innerHTML = `<div class="csub">${otro ? 'Lyra todavía no sabe nada de esta persona.' : 'Todavía no sabe nada de ti. Dile «Lyra, recuerda que…» y lo anota.'}</div>`; return; }
  cont.innerHTML = data.map(m => {
    const cuando = new Date(m.actualizado).toLocaleDateString('es-VE', { day: '2-digit', month: 'short' });
    const editar = ROL === 'admin' ? `<button class="btn-sm" type="button" data-mem-editar="${m.id}" aria-label="Corregir"><i class="fas fa-pen"></i></button>` : '';
    return `<div class="asis-acc"><span class="asis-acc-i"><i class="fas ${m.tipo === 'habito' ? 'fa-chart-simple' : 'fa-bookmark'}"></i></span>`
      + `<div class="asis-acc-b"><b data-mem-texto>${esc(m.texto)}</b><small>${m.tipo === 'habito' ? 'Hábito (se recalcula cada noche)' : 'Dato'} · ${esc(cuando)}</small></div>`
      + `${editar}<button class="btn-sm" type="button" data-mem-borrar="${m.id}" aria-label="Olvidar"><i class="fas fa-xmark"></i></button></div>`;
  }).join('');
}
async function borrarMemoriaLyra(id, btn) {
  if (!Number.isSafeInteger(id)) return;
  const ok = await confirmarSheet({ titulo: '¿Que Lyra lo olvide?', detalle: 'Se borra de su memoria.', textoOk: 'Olvidar', destructivo: true });
  if (!ok) return;
  btn.disabled = true;
  const { data, error } = await sb.rpc('lyra_memoria_borrar', { p_id: id });
  document.getElementById('asis-mem-sub').textContent = error || !data ? 'No se pudo borrar, probá de nuevo.' : 'Listo, lo olvidó.';
  cargarMemoriaLyra();
}
function editarMemoriaLyra(fila, id) {
  const b = fila?.querySelector('[data-mem-texto]');
  if (!b || !Number.isSafeInteger(id) || fila.querySelector('input')) return;
  const inp = document.createElement('input');
  inp.className = 'ei'; inp.maxLength = 300; inp.value = b.textContent; inp.style.width = '100%';
  b.replaceWith(inp); inp.focus();
  let hecho = false;
  const guardar = async ok => {
    if (hecho) return; hecho = true;
    const t = inp.value.trim();
    if (ok && t && t !== b.textContent) {
      const { data, error } = await sb.rpc('lyra_memoria_editar', { p_id: id, p_texto: t });
      document.getElementById('asis-mem-sub').textContent = error || !data ? 'No se pudo guardar la corrección.' : 'Corregido.';
    }
    cargarMemoriaLyra();
  };
  inp.addEventListener('keydown', e => { if (e.key === 'Enter') guardar(true); else if (e.key === 'Escape') guardar(false); });
  inp.addEventListener('blur', () => guardar(true));
}

// Uso para los hábitos: secciones abiertas y horas con actividad (una marca cada 10 min), se vuelca cada 10 min.
const LYRA_USO_CADA_MS = 10 * 60000;
function lyraUsoMarcar(sec) {
  const u = LYRA.uso;
  if (!u) return;
  if (sec) u.secciones[sec] = (u.secciones[sec] || 0) + 1;
  if (Date.now() - u.tHora < LYRA_USO_CADA_MS) return;
  u.tHora = Date.now();
  const h = String(Number(new Date().toLocaleString('en-US', { timeZone: 'America/Caracas', hour: 'numeric', hour12: false })) % 24);
  u.horas[h] = (u.horas[h] || 0) + 1;
}
function lyraUsoVolcar() {
  const u = LYRA.uso;
  if (!u || (!Object.keys(u.secciones).length && !Object.keys(u.horas).length)) return;
  const conteos = { secciones: u.secciones, horas: u.horas };
  u.secciones = {}; u.horas = {};
  sb.rpc('lyra_uso_sumar', { p_conteos: conteos }).then(({ error }) => { if (error) console.warn('Lyra: uso no guardado', error.message); });
}

