const mgUsd = c => '$' + (Number(c || 0) / 100).toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const mgPctTxt = n => Number(n).toLocaleString('es-VE', { maximumFractionDigits: 2 });
