  btn.disabled = !bt;
  if (!bt) { box.innerHTML = '<span class="bt-dato"><i class="fas fa-circle-info"></i> BT Travel todavía no está cargado en Proveedores</span>'; return; }
  const tel = String(bt.telefono || '').replace(/[^\d+]/g, '');
