    visto = Math.max(visto, visto + (techo - visto) * 0.06);
    pintar();
    if (++tick % 10 === 0 && tips.length > 1) {
      tip.classList.add('cambia');
      setTimeout(() => { tip.textContent = tips[++n % tips.length]; tip.classList.remove('cambia'); }, 220);
    }
