// WhatsApp (2026-10-20): en escritorio abre la app de WhatsApp Desktop (protocolo
// whatsapp://), que si ya está abierta solo se trae al frente con el mensaje listo;
// si no hay app instalada, a los 1,6 s cae a WhatsApp Web. En móvil abre la app.
function cbAbrirWhatsapp(tel, texto) {
  const q = `${tel ? `phone=${tel}&` : ''}${texto ? `text=${encodeURIComponent(texto)}` : ''}`;
  const web = `https://wa.me/${tel || ''}?text=${encodeURIComponent(texto)}`;
  if (/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
    location.href = `whatsapp://send?${q}`;
    setTimeout(() => { if (!document.hidden) location.href = web; }, 900);
    return;
  }
  let abrio = false;
  const alSalir = () => { abrio = true; };
  window.addEventListener('blur', alSalir, { once: true });
  location.href = `whatsapp://send?${q}`;
  setTimeout(() => {
    window.removeEventListener('blur', alSalir);
    if (!abrio) location.href = web;
  }, 1600);
}
window.cbWhatsapp = () => {
  const cliente = val('cb-cliente').trim();
  const items = cbItems.map(cbLimpiarItem).filter(it => cbTitulo(it) || it.tarifa);
  const total = cbTotalItems(items), titulos = items.map(it => cbTitulo(it)).filter(Boolean);
  const tel = String(cbLead?.telefono || '').replace(/\D/g, '');
  const extra = titulos.length > 3 ? ` y ${titulos.length - 3} servicio${titulos.length - 3 === 1 ? '' : 's'} más` : '';
  const texto = cliente
    ? `Hola ${cliente}, te comparto la cotización${titulos.length ? ` de ${titulos.slice(0, 3).join(' + ')}${extra}` : ''}${total ? ` por un total de $${cbMonto(total)}` : ''}. Cualquier duda me avisas. — ${MI_NOMBRE}`
    : '';
  cbAbrirWhatsapp(tel, texto);
};
// Stand-by de boletería (2026-10-15): mientras la cotización está ligada a una
// solicitud que atiendo yo, el formulario se autoguarda como borrador de la
// solicitud (2 s después del último cambio) y se recupera al retomarla, también
// desde otro dispositivo. Otro agente o un admin que cotiza una ajena no la pisa.
let cbBorradorTimer = null;
const cbBorradorMio = () => !!cbSolicitud?.la_atiendo_yo;
const cbBorrador = () => ({ v: 2, items: cbItems.map(it => ({ ...Object.fromEntries(Object.entries(it).filter(([k]) => !k.startsWith('_'))), ...(it.tipo === 'hotel' ? { unidad_pendiente: !!it._unidadPendiente } : {}) })), lead: cbLead ? { id: cbLead.id, nombre: cbLead.nombre } : null, cliente: val('cb-cliente'), fecha: val('cb-fecha'), vence: val('cb-vence'), notas: val('cb-notas'), terminos: val('cb-terminos'), asesor: val('cb-asesor') });
function cbProgramarBorrador() {
  if (!cbBorradorMio()) return;
  clearTimeout(cbBorradorTimer); cbBorradorTimer = setTimeout(cbGuardarBorrador, 2000);
}
async function cbGuardarBorrador() {
  const pendiente = cbBorradorTimer != null; clearTimeout(cbBorradorTimer); cbBorradorTimer = null;
  if (!pendiente || !cbBorradorMio()) return true;
  const id = cbSolicitud.id, { data, error } = await sb.rpc('guardar_borrador_solicitud_boleteria', { p_id: Number(id), p_borrador: cbBorrador() });
  const estado = document.getElementById('cb-borrador-estado');
  if (error || !data?.ok) {
    console.error('cbGuardarBorrador', error || data);
    // Ya no está en atención (la resolvió o canceló otro): se deja de autoguardar.
    if (data?.error === 'no_atendiendo' || data?.error === 'no_es_tuya') { if (cbSolicitud?.id === id) { cbSolicitud.la_atiendo_yo = false; cbPintarSolicitud(); } }
    else if (estado) estado.textContent = '· No se pudo guardar el borrador';
    return false;
  }
  if (estado) estado.textContent = `· Borrador guardado ${bolHora(data.borrador_at)}`;
  return true;
}
function cbRestaurarBorrador(b, sel) {
  cbItems = Array.isArray(b.items) && b.items.length ? b.items.map(it => ({ ...cbItemVacio(CB_TIPOS[it?.tipo] ? it.tipo : 'boleto'), ...cbMigrarBoleto(cbMigrarPax(it)), ...(it.tipo === 'hotel' ? { unidad: it.unidad || 'persona', unidad_manual: it.unidad_manual ?? true, _unidadPendiente: it.unidad_pendiente === true, infantes_gratis: it.infantes_gratis === true } : {}) })) : [cbItemVacio()];
  cbRenderItems();
  cbLead = b.lead || null; cbPintarLead();
  cbItems.forEach(it => { if (it.tarifas_contexto && it.tarifas_contexto !== cbTarContexto(it)) { it._desactualizado = true; it._aviso = 'Revisa y confirma los precios del borrador para las fechas actuales.'; } });
  cbRenderItems();
  cbItems.forEach(it => {
    if (it.tipo !== 'hotel') return;
    if (!it.producto_id) return;
    Promise.all([cbTraerTarifas(it.producto_id), cbTraerHabitaciones(it.producto_id)]).then(() => { if (cbItems.includes(it)) cbRenderItems(); }).catch(() => {});
  });
  [['cb-cliente', b.cliente], ['cb-fecha', b.fecha], ['cb-vence', b.vence], ['cb-notas', b.notas], ['cb-terminos', b.terminos]].forEach(([id, v]) => { if (typeof v === 'string') document.getElementById(id).value = v; });
  // Un borrador de días atrás trae la fecha y la vigencia de entonces: vuelven a hoy.
  ['cb-fecha', 'cb-vence'].forEach(id => { const el = document.getElementById(id); if (el.value && el.value < cbHoy()) el.value = cbHoy(); });
  if (b.asesor && [...sel.options].some(o => o.value === b.asesor)) sel.value = b.asesor;
  cbResumenCliente();
}
async function cbAplicarSolicitud(sel) {
  const s = cbSolicitudPendiente; cbSolicitudPendiente = null;
  if (cbSolicitud && String(cbSolicitud.id) !== String(s.id)) await cbGuardarBorrador();
  // Retomar: reanudar saca la pausa y trae el borrador; sin borrador se prellena con la solicitud.
  let borrador = null;
  if (s.la_atiendo_yo && (s.pausada_en || s.tiene_borrador)) {
    const { data, error } = await sb.rpc('reanudar_solicitud_boleteria', { p_id: Number(s.id) });
    if (error || !data?.ok) errToast('No se pudo recuperar lo avanzado de la solicitud #' + s.id);
    else { borrador = data.borrador; s.pausada_en = null; }
  }
  cbResetForm(); cbSolicitud = s; cbPintarSolicitud();
  if (borrador) { cbRestaurarBorrador(borrador, sel); okToast(`Retomaste la solicitud #${s.id} donde la dejaste`); return; }
  document.getElementById('cb-cliente').value = s.cliente_nombre || '';
  await bolAsegurarCatalogo();
  const o = bolIataDe(s.origen) || '', d = bolIataDe(s.destino) || '';
  cbItems = [{ ...cbItemVacio('boleto'), origen: o, destino: d, viaje: s.fecha_regreso ? 'rt' : 'ow', ruta_libre: !(o && d), ruta: o && d ? '' : [s.origen, s.destino, s.fecha_regreso ? s.origen : ''].filter(Boolean).join(' - '), adultos: s.adultos || s.personas || 1, ninos: s.ninos || '', infantes: s.infantes || '', ida: s.fecha_viaje || '', vuelta: s.fecha_regreso || '', extra: s.notas || '' }];
  cbSyncRuta(cbItems[0]); cbRenderItems();
  // listar_cola_boleteria trae el nombre de quien pidió, no su id.
  const op = [...sel.options].find(o => o.value && o.textContent.replace(/ \(admin\)$/, '') === s.creado_por);
  if (op) sel.value = op.value;
}
// "Guardar y volver a la cola": la deja en stand-by con lo armado y vuelve a la cola.
window.cbPausarYVolver = async btn => {
  const s = cbSolicitud; if (!s) return;
  clearTimeout(cbBorradorTimer); cbBorradorTimer = null;
  btn.disabled = true;
  const ok = await bolPausar(s.id, cbBorrador());
  btn.disabled = false;
  if (!ok) return;
  cbResetForm();
  if (NAV_STACK.at(-1)?.type === 'section') navConsume(); else activateSection('bol-solicitudes');
};
async function cbResolverSolicitud(solId, cot) {
  const { data, error } = await sb.rpc('resolver_solicitud_boleteria', { p_id: Number(solId), p_resultado: `Cotización ${cbNumero(cot.numero)} enviada` });
  if (error || (!data?.ok && data?.error !== 'no_disponible')) errToast(`No se pudo marcar resuelta la solicitud #${solId}: hazlo desde Solicitudes`);
  return !!data?.ok;
}
function cbResetForm() {
  DR?.cancelar('cotizacion');
  ['cb-fecha', 'cb-vence'].forEach(id => { document.getElementById(id).min = cbHoy(); });
  clearTimeout(cbBorradorTimer); cbBorradorTimer = null;
  cbSolicitud = null; cbPintarSolicitud();
  cbLead = null; cbPintarLead();
  cbLeadTk++; clearTimeout(cbLeadTimer); cbLeadsRes = [];
  const busca = document.getElementById('cb-lead-q'), res = document.getElementById('cb-lead-res');
  if (busca) busca.value = ''; if (res) res.hidden = true;
  cbItems = [cbItemVacio(cbModo === 'ventas' ? 'hotel' : 'boleto')]; cbRenderItems();
  document.getElementById('cb-cliente').value = '';
  document.getElementById('cb-fecha').value = cbHoy(); document.getElementById('cb-vence').value = cbHoy();
  document.getElementById('cb-notas').value = CB_NOTAS; document.getElementById('cb-terminos').value = CB_TERMINOS;
  document.getElementById('cb-cliente-seccion').open = true; cbResumenCliente();
}
async function cbCargarSeccion() {
  const modo = cbLeadPendiente || (!cbSolicitudPendiente && !document.body.classList.contains('modo-boleteria')) ? 'ventas' : 'boleteria';
  const primera = !cbListo, cambio = modo !== cbModo;
  if (cambio && !primera) await cbGuardarBorrador();
  cbModo = modo;
  document.getElementById('sec-cotizacion-boletos').classList.toggle('cb-modo-ventas', modo === 'ventas');
  if (primera || cambio) document.getElementById('cb-origen').value = modo;
  if (cambio && !primera) cbResetForm();
  cbCargarProductos();
  bolAsegurarCatalogo().then(cbRefrescarRutas);
  ['cb-fecha', 'cb-vence'].forEach(id => { document.getElementById(id).min = cbHoy(); });
  if (!cbListo) {
    cbListo = true;
    const leadInput = document.getElementById('cb-lead-q'), leadBox = document.getElementById('cb-lead-res');
    leadInput.addEventListener('input', () => {
      cbLeadTk++; clearTimeout(cbLeadTimer); cbLeadsRes = [];
      cbPintarBusquedaLead(leadBusqueda(leadInput.value));
      cbLeadTimer = setTimeout(cbBuscarLead, 280);
    });
    leadInput.addEventListener('keydown', e => cbPickerTeclas(e, leadBox, op => cbElegirLead(+op.dataset.cbLead)));
    leadInput.addEventListener('focusout', () => { cbLeadTk++; clearTimeout(cbLeadTimer); leadBox.hidden = true; leadInput.setAttribute('aria-expanded', 'false'); });
    leadBox.addEventListener('mousedown', e => { const op = e.target.closest('[data-cb-lead]'); if (op) { e.preventDefault(); cbElegirLead(+op.dataset.cbLead); } });
    // "Válida hasta" sigue a la fecha de la cotización (pedido del dueño 2026-10-17); se puede alargar a mano.
    document.getElementById('cb-fecha').addEventListener('input', e => {
      const v = document.getElementById('cb-vence'), f = e.target.value;
      if (!f) return;
      v.min = f > cbHoy() ? f : cbHoy();
      v.value = f;
      cbProgramarBorrador();
    });
    cbResetForm();
    document.getElementById('cb-origen').addEventListener('change', () => { cbOffset = 0; cbCargarHistorial(false); });
    const cbLista = document.getElementById('cb-items');
    cbLista.addEventListener('error', e => { if (e.target.matches('.cb-hotel-foto')) e.target.remove(); }, true);
    cbLista.addEventListener('focusin', e => { if (e.target.matches('.cb-ap-in')) { e.target.select(); cbApAbrir(e.target); } });
    cbLista.addEventListener('focusin', e => { if (e.target.dataset.busca === 'hotel') cbHotelBuscar(e.target); });
    cbLista.addEventListener('focusout', e => { if (e.target.dataset.busca === 'hotel') { e.target.parentElement.querySelector('.cb-picker-lista').hidden = true; e.target.setAttribute('aria-expanded', 'false'); } });
    cbLista.addEventListener('pointerdown', e => {
      const hab = e.target.closest('[data-cb-hab]');
      if (hab) { e.preventDefault(); return; }
      const op = e.target.closest('[data-cb-hotel]');
      if (op) { e.preventDefault(); cbHotelElegir(op.closest('.cb-item'), op.dataset.cbHotel); }
    });
    cbLista.addEventListener('keydown', e => {
      if (e.target.matches('[data-cb-hab-abrir]')) {
        const box = e.target.closest('.cb-picker'), lista = box.querySelector('.cb-picker-lista');
        if (e.key === 'Tab') { cbHabCerrar(box); return; }
        if (e.key === 'Escape') { cbHabCerrar(box); return; }
        if ((e.key === 'Enter' || e.key === ' ') && lista.hidden) { e.preventDefault(); lista.hidden = false; e.target.setAttribute('aria-expanded', 'true'); return; }
        cbPickerTeclas(e, lista, cbHabElegir); return;
      }
      if (e.target.dataset.busca === 'hotel') cbPickerTeclas(e, e.target.parentElement.querySelector('.cb-picker-lista'), op => cbHotelElegir(op.closest('.cb-item'), op.dataset.cbHotel));
    });
    cbLista.addEventListener('focusout', e => { if (e.target.matches('.cb-ap-in')) cbApConfirmar(e.target); });
    // mousedown y no click: así la opción se elige antes del blur del input.
    cbLista.addEventListener('mousedown', e => {
      const op = e.target.closest('.cb-ap-op'); if (!op) return;
      e.preventDefault(); cbApElegir(op.closest('.cb-ap').querySelector('.cb-ap-in'), op.dataset.code);
    });
    cbLista.addEventListener('keydown', e => {
      const inp = e.target; if (!inp.matches('.cb-ap-in')) return;
      const lista = inp.closest('.cb-ap').querySelector('.cb-ap-lista'), ops = [...lista.querySelectorAll('.cb-ap-op')];
      const i = ops.findIndex(o => o.classList.contains('activo'));
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault(); if (lista.hidden) { cbApAbrir(inp); return; }
        if (!ops.length) return;
        const n = (i + (e.key === 'ArrowDown' ? 1 : -1) + ops.length) % ops.length;
        ops.forEach((o, j) => o.classList.toggle('activo', j === n)); ops[n].scrollIntoView({ block: 'nearest' });
      } else if (e.key === 'Enter') { e.preventDefault(); if (i >= 0 && !lista.hidden) cbApElegir(inp, ops[i].dataset.code); else cbApConfirmar(inp); }
      else if (e.key === 'Escape') { cbApCerrar(inp); }
    });
    cbLista.addEventListener('click', e => {
      const hab = e.target.closest('[data-cb-hab]'); if (hab) { cbHabElegir(hab); return; }
      const abrir = e.target.closest('[data-cb-hab-abrir]');
      if (abrir) { const lista = abrir.parentElement.querySelector('.cb-picker-lista'); lista.hidden = !lista.hidden; abrir.setAttribute('aria-expanded', String(!lista.hidden)); return; }
      const hotel = e.target.closest('[data-cb-hotel]');
      if (hotel) { cbHotelElegir(hotel.closest('.cb-item'), hotel.dataset.cbHotel); return; }
      const card = e.target.closest('.cb-item'); if (!card) return;
      const it = cbItems[+card.dataset.i], viaje = e.target.closest('[data-viaje]'), ref = e.target.closest('.cb-ref-usar');
      if (e.target.closest('[data-cb-hab-fotos]')) { const fotos = cbHabitacionFotos(it, it.hab); if (fotos.length) openLightbox(fotos.map(f => fotoGrande(f.storage_path)), 0); return; }
      if (e.target.closest('[data-cb-fotos-reintentar]')) { cbTraerHabitaciones(it.producto_id).then(() => { if (cbItems.includes(it)) cbRenderItems(); }); return; }
      if (e.target.closest('[data-cb-reintentar]')) { cbHotelElegir(card, it.producto_id); return; }
      if (e.target.closest('[data-cb-plegar]')) { it._plegado = !it._plegado; cbRenderItems(); document.querySelector(`#cb-items .cb-item[data-i="${card.dataset.i}"] [data-cb-plegar]`).focus({ preventScroll: true }); return; }
      if (e.target.closest('[data-cb-unidad-cambiar]')) { it._unidadEditar = true; cbRenderItems(); document.getElementById(`cb-unidad-${card.dataset.i}`)?.focus(); return; }
      if (e.target.closest('[data-cb-usar]')) { cbHotelRecalcular(it, true); cbRenderItems(); cbProgramarBorrador(); return; }
      if (e.target.closest('[data-cb-manual]')) {
        it.tramos = []; it.tarifas_contexto = cbTarContexto(it); it._desactualizado = false;
        it._aviso = 'Tarifa manual confirmada para estas fechas y ocupación.'; cbRenderItems(); cbProgramarBorrador(); return;
      }
      if (viaje) { if (it.viaje === viaje.dataset.viaje) return; it.viaje = viaje.dataset.viaje; cbSyncRuta(it); cbPintarRuta(card, it); cbProgramarBorrador(); }
      else if (e.target.closest('.cb-ap-swap')) {
        [it.origen, it.destino] = [it.destino, it.origen]; cbSyncRuta(it);
        card.querySelectorAll('.cb-ap-in').forEach(inp => { inp.value = cbApTexto(it[inp.dataset.ap]); inp.closest('.cb-ap').querySelector('.cb-ap-nota').innerHTML = cbApNota(it[inp.dataset.ap]); });
        card.querySelector('.cb-ap-swap').classList.remove('girando'); void card.offsetWidth; card.querySelector('.cb-ap-swap').classList.add('girando');
        cbPintarRuta(card, it); cbProgramarBorrador();
      } else if (ref) {
        it.tarifa = ref.dataset.ref; const inp = card.querySelector('[data-k="tarifa"]'); if (inp) inp.value = it.tarifa;
        card.querySelector('.cb-importe').textContent = cbImporteTexto(it); cbActualizarTotal(); cbProgramarBorrador();
      }
    });
    cbLista.addEventListener('input', e => {
      if (e.target.matches('.cb-ap-in')) { cbApAbrir(e.target); return; }
      const k = e.target.dataset.k, card = e.target.closest('.cb-item');
      if (card && e.target.dataset.tramo !== undefined) {
        const it = cbItems[+card.dataset.i], t = it.tramos[+e.target.dataset.tramo];
        t.tarifa = Number(e.target.value) || 0; t.tarifa_habitacion = null; it.tarifa_manual = true;
        if (+e.target.dataset.tramo === 0) it.tarifa = t.tarifa;
        if (cbTarTramosValidos(it)) it.tarifas_contexto = cbTarContexto(it);
        card.querySelector('.cb-importe').textContent = cbImporteTexto(it); cbActualizarTotal(); cbProgramarBorrador(); return;
      }
      if (!k || !card) return;
      const it = cbItems[+card.dataset.i], previo = it[k]; it[k] = e.target.value;
      if (it.tipo === 'hotel' && k === 'unidad') {
        it.unidad_manual = true; it._unidadPendiente = false; it.tarifa_manual = false;
        it.tarifa = ''; it.tarifa_nino = ''; it.tarifa_nino_auto = true; it.tramos = []; it.tarifas_contexto = ''; it.tarifa_variante = '';
      }
      if (it.tipo === 'hotel' && k === 'tarifa_variante') { it.variante_auto = false; it.tramos = []; it.tarifa = ''; it.tarifa_manual = false; it.tarifas_contexto = ''; }
      if (e.target.dataset.busca === 'hotel') {
        if (it.producto_id) {
          card.querySelector('.cb-hotel-foto')?.remove();
          delete it.producto_id; it.tramos = []; if (!it.tarifa_manual) it.tarifa = '';
          it._cargaHotel = (it._cargaHotel || 0) + 1; it._cargando = false; it._tarifaError = false;
          it.plan = ''; it.hab = ''; it.plan_libre = false; it.hab_libre = false; it.tarifa_avisos = [];
          it.unidad_manual = false; it._unidadPendiente = true; it.tarifa_variante = '';
          card.querySelectorAll('.cb-hotel-selector').forEach(el => {
            const campo = el.querySelector('select')?.dataset.cbCampo || 'hab';
            el.outerHTML = cbHotelSelectorHtml(it, +card.dataset.i, campo, campo === 'plan' ? 'Plan' : 'Habitación');
          });
        }
        const precio = card.querySelector('[data-k=tarifa]'); if (precio) precio.value = it.tarifa || '';
        cbHotelBuscar(e.target);
      }
      if (it.tipo === 'hotel' && k === 'tarifa') {
        it.tarifa_manual = true; it.tarifas_contexto = cbTarContexto(it);
        if (it.tramos?.length === 1) { it.tramos[0].tarifa = Number(it.tarifa) || 0; it.tramos[0].tarifa_habitacion = null; }
      }
      if (it.tipo === 'hotel' && k === 'tarifa_nino') {
        it.tarifa_nino_auto = false; it.tarifa_nino_contexto = cbTarContexto(it);
      }
      if (it.tipo === 'hotel' && k === 'ninos') {
        if (!(Number(previo) > 0)) it.tarifa_nino_auto = true;
        cbHotelRecalcular(it);
        const nino = card.querySelector('[data-k="tarifa_nino"]'); if (nino) nino.value = it.tarifa_nino ?? '';
        const detalle = card.querySelector('.cb-tarifario');
        if (detalle) detalle.outerHTML = cbHotelPrecioHtml(it, +card.dataset.i);
      }
      if (k === 'ida') { const vuelta = card.querySelector('[data-k="vuelta"]'); if (vuelta) vuelta.min = cbMinFecha('vuelta', it.ida); }
      if (k === 'tipo') { cbItems[+card.dataset.i] = cbItemVacio(it.tipo); cbRenderItems(); return; }
      card.querySelector('.cb-importe').textContent = cbImporteTexto(it);
      cbActualizarTotal();
    });
    cbLista.addEventListener('change', e => {
      const k = e.target.dataset.k, card = e.target.closest('.cb-item'); if (!card) return;
      const it = cbItems[+card.dataset.i];
      if (it.tipo !== 'hotel') return;
      const campo = e.target.dataset.cbCampo;
      if (campo) {
        cbHotelCambiarOpcion(it, campo, e.target.value); cbRenderItems(); cbProgramarBorrador();
        if (it[campo + '_libre']) document.getElementById(`cb-${campo}-${card.dataset.i}-manual`)?.focus();
        return;
      }
      if (k === 'hab') it.habitacion_manual = true;
      if (k === 'unidad' && !it.unidad_manual) { it.unidad = e.target.value; it.unidad_manual = true; it._unidadPendiente = false; it.tarifa_manual = false; it.tarifa = ''; it.tramos = []; it.tarifas_contexto = ''; }
      if (['nombre', 'ida', 'vuelta', 'adultos', 'plan', 'hab', 'unidad', 'tarifa', 'tarifa_variante', 'habitaciones'].includes(k)) {
        if (k === 'plan' && !it.tarifa_manual && cbTarOpciones(cbHotelFilas(it), 'plan').length) { it.hab = ''; it.habitacion_manual = false; }
        cbHotelRecalcular(it); cbRenderItems(); cbProgramarBorrador();
      }
    });
    cbLista.addEventListener('focusout', e => {
      const box = e.target.closest('.cb-picker');
      if (box?.querySelector('[data-cb-hab-abrir]') && !box.contains(e.relatedTarget)) cbHabCerrar(box);
    });
    document.addEventListener('pointerdown', e => {
      cbLista.querySelectorAll('[data-cb-hab-abrir]').forEach(b => { if (!b.parentElement.contains(e.target)) cbHabCerrar(b.parentElement); });
    });
    // Escribir la fecha a mano se salta el min del calendario: al salir del campo, una fecha pasada se borra.
    document.getElementById('sec-cotizacion-boletos').addEventListener('focusout', e => {
      const inp = e.target;
      if (inp.type !== 'date' || !inp.min || !inp.value || inp.value >= inp.min) return;
      inp.value = '';
      inp.dispatchEvent(new Event('input', { bubbles: true }));
      errToast(inp.min > cbHoy() ? 'La vuelta no puede ser anterior a la ida' : 'No se puede elegir una fecha anterior a hoy');
    });
    document.getElementById('cb-buscar').addEventListener('input', () => { clearTimeout(cbBuscarTimer); cbBuscarTimer = setTimeout(() => { cbOffset = 0; cbCargarHistorial(false); }, 280); });
    const camposBorrador = ['cb-cliente', 'cb-fecha', 'cb-vence', 'cb-notas', 'cb-terminos', 'cb-asesor'];
    ['input', 'change'].forEach(ev => document.getElementById('sec-cotizacion-boletos').addEventListener(ev, e => {
      if (e.target.closest('#cb-items') || camposBorrador.includes(e.target.id)) cbProgramarBorrador();
      if (camposBorrador.includes(e.target.id)) cbResumenCliente();
    }));
    document.addEventListener('visibilitychange', () => { if (document.hidden) cbGuardarBorrador(); });
  }
  const staff = await cargarUsuariosStaff();
  const sel = document.getElementById('cb-asesor'), previo = sel.value;
  // usuarios_chat no trae es_prueba: las cuentas de prueba se reconocen por nombre (__gate_*, Invitado N, "Prueba ...").
  const asesores = staff.filter(u => u.id !== MI_USUARIO_ID && (u.rol === 'asesor' || u.rol === 'admin') && !/^__gate|prueba|invitado/i.test(u.nombre || ''))
    .sort((a, b) => (a.rol === b.rol ? 0 : a.rol === 'asesor' ? -1 : 1) || (a.nombre || '').localeCompare(b.nombre || ''));
  // usuarios_chat solo le devuelve admins a un asesor común (el chat no le deja escribirle a otro asesor ni a sí mismo):
  // cotiza para sí, así que el campo va fijo con su nombre y el PDF se descarga en vez de mandarse por chat.
  const cotizaParaSi = ROL === 'asesor' && !MI_ES_BOLETERIA;
  sel.disabled = cotizaParaSi;
  document.getElementById('cb-enviar-btn').style.display = cotizaParaSi ? 'none' : '';
  if (cotizaParaSi) sel.innerHTML = `<option value="${esc(MI_USUARIO_ID)}" selected>${esc(MI_NOMBRE)}</option>`;
  else sel.innerHTML = '<option value="">— Elige el asesor —</option>' + asesores.map(u => `<option value="${esc(u.id)}"${u.id === previo ? ' selected' : ''}>${esc(u.nombre)}${u.rol === 'admin' ? ' (admin)' : ''}</option>`).join('');
  if (cbSolicitudPendiente) await cbAplicarSolicitud(sel);
  if (cbLeadPendiente) cbAplicarLead();
  cbResumenCliente();
  cbOffset = 0;
  await cbCargarHistorial(false);
}
window.cbVerHistorial = () => {
  const titulo = document.getElementById('cb-historial-titulo');
  titulo?.scrollIntoView({ block: 'start' });
  titulo?.focus({ preventScroll: true });
};
async function cbCargarRecientes() {
  const lista = document.getElementById('cb-recientes-lista');
  if (!lista) return;
  lista.setAttribute('aria-busy', 'true');
  try {
    // Independiente de los filtros del registro; conserva los permisos de la sesión.
    const { data, error } = await sb.from('cotizaciones_boleteria').select('*').is('anulado_en', null).order('created_at', { ascending: false }).limit(3);
    if (error) throw error;
    (data || []).forEach(c => cbFilas.set(c.id, c));
    lista.innerHTML = (data || []).map((c, i) => {
      const detalle = (c.items || []).map(cbTitulo).filter(Boolean).join(' · ') || 'Sin servicios';
      return `<button class="vc-reciente" type="button" data-cb-reciente="${i}" aria-label="${esc('Ver PDF de la cotización ' + cbNumero(c.numero) + ' de ' + c.cliente)}">
        <b title="${esc(c.cliente)}">${esc(c.cliente)}</b><span class="vc-reciente-num">${esc(cbNumero(c.numero))}</span>
        <small title="${esc(detalle)}">${esc(detalle)}</small>
        <span class="vc-reciente-total">$${cbMonto(c.total)}<i class="fas fa-file-pdf" aria-hidden="true"></i></span>
        <small title="${esc(c.creado_por_nombre || '')}">${esc(c.creado_por_nombre || '—')} · ${esc((c.created_at || '').slice(0, 10))}</small>
      </button>`;
    }).join('') || '<p class="vc-recientes-estado">Aún no hay cotizaciones generadas.</p>';
    lista.querySelectorAll('[data-cb-reciente]').forEach(b => b.onclick = () => window.cbVerPdf(data[Number(b.dataset.cbReciente)].id));
  } catch (_) {
    lista.innerHTML = '<p class="vc-recientes-estado">No se pudieron cargar las cotizaciones.</p><button class="vc-link" type="button" onclick="cbCargarRecientes()">Reintentar</button>';
  } finally {
    lista.setAttribute('aria-busy', 'false');
  }
}
window.cbCargarRecientes = cbCargarRecientes;
async function cbCargarHistorial(append) {
  const recientes = append ? Promise.resolve() : cbCargarRecientes();
  const cont = document.getElementById('cb-historial'), mas = document.getElementById('cb-cargar-mas-btn');
  if (!append) document.getElementById('cb-historial-loading')?.classList.add('show');
  let q = sb.from('cotizaciones_boleteria').select('*');
  q = val('cb-documentos-estado') === 'anulados' ? q.not('anulado_en', 'is', null) : q.is('anulado_en', null);
  // Sin comas/paréntesis -- romperían la sintaxis del filtro .or() de PostgREST.
  const buscar = (val('cb-buscar') || '').trim().replace(/[,()]/g, '');
  if (buscar) q = q.or(`cliente.ilike.%${buscar}%,enviado_a_nombre.ilike.%${buscar}%,creado_por_nombre.ilike.%${buscar}%`);
  if (val('cb-origen')) q = q.eq('origen', val('cb-origen'));
  const { data, error } = await q.order('created_at', { ascending: false }).range(cbOffset, cbOffset + CB_PAGE_SIZE - 1);
  document.getElementById('cb-historial-loading')?.classList.remove('show');
  await recientes;
  if (error) { if (!append) cont.innerHTML = '<div class="lt-vacio"><i class="fas fa-triangle-exclamation"></i> No se pudo cargar el historial</div>'; return; }
  (data || []).forEach(c => cbFilas.set(c.id, c));
  const filas = (data || []).map((c, i) => {
    const rutas = (c.items || []).map(cbTitulo).filter(Boolean).join(' · ') || '—', ventas = c.origen === 'ventas';
    return `<article class="lt-card" style="--i:${Math.min(i, 20)}">
    <div class="lt-card-cab">
      <div class="lt-card-tit" title="${esc(c.cliente)}">${esc(c.cliente)}</div>
      <span class="bt-tag" style="--c:var(--${ventas ? 'green' : 'blue'})" title="${ventas ? 'Cotización de ventas' : 'Cotización de Boletería'}">${cbNumero(c.numero)}</span>
    </div>
    <div class="lt-card-meta"><i class="fas fa-user"></i> ${esc(c.creado_por_nombre || '—')} · ${esc(cbFechaLarga(c.fecha))}${c.solicitud_id ? ` · <i class="fas fa-plane-departure"></i> Solicitud #${c.solicitud_id}` : ''}${c.lead_id ? ` · <i class="fas fa-address-card"></i> Lead #${c.lead_id}` : ''}</div>
    <div class="lt-cifras" style="grid-template-columns:2fr 1fr">
      <div><span>Detalle</span><b title="${esc(rutas)}">${esc(rutas)}</b></div>
      <div><span>Total</span><b>$${cbMonto(c.total)}</b></div>
    </div>
    <div class="lt-card-meta">${ventas ? '<i class="fas fa-user-check"></i> Para el cliente' : c.enviado_a ? `<i class="fas fa-paper-plane"></i> Enviada a ${esc(c.enviado_a_nombre || 'asesor')}` : '<i class="fas fa-circle-minus"></i> Sin enviar'}</div>
    <div class="lt-card-pie">
      <button class="btn-sm lt-primario" type="button" onclick="cbVerPdf('${c.id}')"><i class="fas fa-file-pdf"></i> Ver PDF</button>
      ${DR?.acciones('cotizacion', c) || ''}
      ${!c.anulado_en && ventas ? (c.lead_id ? `<button class="btn-sm" type="button" onclick="cbReintentarLead('${c.id}', this)">Registrar en lead</button>` : '') : ''}
    </div>
  </article>`;
  }).join('');
  if (!append && !filas) cont.innerHTML = '<div class="lt-vacio"><i class="fas fa-inbox"></i> Sin cotizaciones</div>';
  else cont.innerHTML = append ? cont.innerHTML + filas : filas;
  if (!append) entradaLista(cont);
  if (mas) mas.style.display = (data || []).length < CB_PAGE_SIZE ? 'none' : '';
}
window.cbCargarMas = () => { cbOffset += CB_PAGE_SIZE; cbCargarHistorial(true); };

async function cbEnviarAAsesor(c, blob, asesorId) {
  if (DR) return DR.enviarCotizacion(c, asesorId, blob);
  const nombre = cbArchivo(c);
  const { data: convId, error } = await sb.rpc('obtener_o_crear_conversacion_directa', { p_otro_usuario_id: asesorId });
  if (error || !convId) return false;
  const path = `${convId}/${crypto.randomUUID()}-${nombre}`;
  const { error: upErr } = await sb.storage.from('chat-interno-adjuntos').upload(path, blob, { contentType: 'application/pdf' });
  if (upErr) return false;
  const { data, error: msgErr } = await sb.rpc('enviar_mensaje', { p_conversacion_id: convId, p_tipo: 'documento', p_storage_path: path, p_nombre_archivo: nombre, p_peso_bytes: blob.size });
  if (msgErr || !data?.ok) { await sb.storage.from('chat-interno-adjuntos').remove([path]); return false; }
  await sb.rpc('enviar_mensaje', { p_conversacion_id: convId, p_tipo: 'texto', p_contenido: `Cotización ${cbNumero(c.numero)} · ${c.cliente} · $${cbMonto(c.total)}` });
  const envio = { enviado_a: asesorId, enviado_a_nombre: nombreUsuario(asesorId), enviado_at: new Date().toISOString(), pdf_path: path };
  await sb.from('cotizaciones_boleteria').update(envio).eq('id', c.id);
  Object.assign(c, envio);
  return true;
}
let cbGenerando = false;
// accion: 'enviar' | 'descargar' (Boletería y ventas) | 'compartir' | 'lead' (solo ventas).
window.cbGuardar = async function cbGuardar(accion) {
  if (cbGenerando) return;
  const enviar = accion === 'enviar', ventas = cbModo === 'ventas';
  const cliente = val('cb-cliente').trim();
  if (!cliente) { errToast('Escribe el cliente'); docEnfocar('cb-cliente'); return; }
  const hotelPendiente = cbItems.find(it => it.tipo === 'hotel' && (it._cargando || it._unidadPendiente || it._desactualizado || !cbTarTramosValidos(it) || (it.tarifas_contexto && it.tarifas_contexto !== cbTarContexto(it)) || ((it.infantes_gratis || cbPorHabitacion(it)) && (!cbTarNoches(it.ida, it.vuelta).length || cbTarNum(it.tarifa) === null)) || (cbPorHabitacion(it) && (!Number.isInteger(cbHabitaciones(it)) || cbHabitaciones(it) < 1))));
  if (hotelPendiente) { errToast('Hospedaje: revisa las fechas y confirma una tarifa para el viaje actual.'); cbEnfocarServicio(hotelPendiente, 'ida'); return; }
  const ninosSinTarifa = cbItems.find(it => it.tipo === 'hotel' && !cbPorHabitacion(it) && Number(it.ninos) > 0 && (cbTarNum(it.tarifa_nino) === null || (it.tramos || []).some(t => cbTarNinoTramo(it, t) === null)));
  if (ninosSinTarifa) { errToast('Hospedaje: indica la tarifa de los niños; escribe 0 si la promoción los incluye gratis.'); cbEnfocarServicio(ninosSinTarifa, 'tarifa_nino'); return; }
  const registros = cbItems.map(it => ({ original: it, datos: cbLimpiarItem(it) })).filter(({ datos }) => cbTitulo(datos) || datos.tarifa);
  const items = registros.map(({ datos }) => datos);
  if (!items.length) { errToast('Agrega al menos un servicio con su descripción y tarifa'); cbEnfocarServicio(cbItems[0], 'nombre'); return; }
  const incompleto = items.find(it => !cbTitulo(it) || !(cbEsPax(it) ? cbPax(it).a : it.cant));
  if (incompleto) { const t = cbTipo(incompleto), falta = !cbTitulo(incompleto) ? t.campos[0][1] : cbEsPax(incompleto) ? 'al menos un adulto' : t.campos.find(([k]) => k === 'cant')[1]; errToast(`${t.nombre}: falta ${falta.toLowerCase()}`); cbEnfocarServicio(registros[items.indexOf(incompleto)].original, !cbTitulo(incompleto) ? t.campos[0][0] : cbEsPax(incompleto) ? 'adultos' : 'cant'); return; }
  const pasada = items.find(it => [it.ida, it.vuelta].some(d => d && d < cbHoy()));
  if (pasada && !DR?.edicion('cotizacion')) { errToast(`${cbTipo(pasada).nombre}: hay una fecha anterior a hoy`); cbEnfocarServicio(registros[items.indexOf(pasada)].original, pasada.ida && pasada.ida < cbHoy() ? 'ida' : 'vuelta'); return; }
  if (!DR?.edicion('cotizacion') && [val('cb-fecha'), val('cb-vence')].some(d => d && d < cbHoy())) { errToast('La fecha y la vigencia no pueden ser anteriores a hoy'); docEnfocar(val('cb-fecha') && val('cb-fecha') < cbHoy() ? 'cb-fecha' : 'cb-vence'); return; }
  const asesorId = val('cb-asesor');
  if (enviar && !asesorId) { errToast('Elige a qué asesor mandarla'); docEnfocar('cb-asesor'); return; }
  const btn = document.getElementById(`cb-${accion}-btn`), htmlBtn = btn.dataset.drEtiqueta || btn.innerHTML;
  cbGenerando = true; document.querySelectorAll('.cb-acciones button').forEach(b => b.disabled = true);
  btn.disabled = true; btn.innerHTML = 'Generando... <i class="fas fa-spinner fa-spin"></i>';
  const sol = ventas ? null : cbSolicitud, lead = ventas ? cbLead : null;
  try {
    const fila = {
      creado_por: MI_USUARIO_ID, creado_por_nombre: MI_NOMBRE, cliente, fecha: val('cb-fecha') || cbHoy(), vence: val('cb-vence') || null,
      items, total: cbTotalItems(items), notas: val('cb-notas').trim() || null, terminos: val('cb-terminos').trim() || null,
      solicitud_id: sol?.id ?? null, solicitud_revision: sol?.revision ?? null, origen: cbModo, lead_id: lead?.id ?? null,
    };
    if (DR?.edicion('cotizacion')) { await DR.guardar('cotizacion', { ...fila, items: items.map(it => ({ ...it, importe_revision: cbImporte(it) })) }); return; }
    const { data: cot, error } = await sb.from('cotizaciones_boleteria').insert(fila).select().single();
    if (error || !cot) { errToast('No se pudo guardar la cotización: ' + (error?.message || '')); return; }
    cbResetForm();
    try {
      await ensureVoucherLibs();
      const blob = await cbPdfDe(cot), num = cbNumero(cot.numero);
      if (ventas) {
        let marca = '';
        if (lead) marca = await cbRegistrarLeadCot(cot);
        if (accion === 'compartir') await cbCompartir(blob, cbArchivo(cot));
        else if (accion === 'lead') await pdfEntregar(blob, cbArchivo(cot));
        else cbDescargar(blob, cbArchivo(cot));
        okToast(`Cotización ${num} generada${marca}`);
      }
      else if (!enviar || asesorId === MI_USUARIO_ID) { cbDescargar(blob, cbArchivo(cot)); okToast(`Cotización ${cbNumero(cot.numero)} generada`); }
      else if (await cbEnviarAAsesor(cot, blob, asesorId)) {
        const resuelta = sol && await cbResolverSolicitud(sol.id, cot);
        okToast(`${cbNumero(cot.numero)} enviada a ${nombreUsuario(asesorId)}${resuelta ? ` · solicitud #${sol.id} resuelta` : ''}`);
      }
      else errToast(`${cbNumero(cot.numero)} se guardó pero no se pudo enviar: reenvíala desde el historial`);
    } catch (e) {
      console.error('cbGuardar pdf', e);
      errToast(`${cbNumero(cot.numero)} se guardó pero no se pudo generar el PDF: reintenta desde el historial`);
    }
    cbOffset = 0; cbCargarHistorial(false);
  } finally {
    cbGenerando = false; document.querySelectorAll('.cb-acciones button').forEach(b => b.disabled = false);
    btn.disabled = false; btn.innerHTML = DR?.edicion('cotizacion') ? '<i class="fas fa-file-pdf"></i> Guardar revisión' : htmlBtn;
  }
};
async function cbRegistrarLeadCot(cot) {
  if (!cot.lead_id) return '';
  try {
    const { data: lead, error: lectura } = await sb.from('leads').select('id,estado').eq('id', cot.lead_id).is('eliminado_at', null).maybeSingle();
    if (lectura || !lead) throw new Error('No se pudo consultar el lead');
    if (!['POR ATENDER', 'ATENDIDO', 'COTIZACION ENVIADA'].includes(lead.estado)) return ' · estado del lead conservado';
    const { data, error } = await sb.rpc('registrar_cotizacion_enviada', { p_lead_id: cot.lead_id });
    if (error || !data?.ok) throw new Error(error?.message || data?.error || 'sin respuesta');
    ACTIVIDAD_CACHE = null;
    if (currentLead?.id === cot.lead_id) {
      currentLead.estado = data.estado;
      if (data.fecha_cotizacion_enviada) currentLead.fecha_cotizacion_enviada = data.fecha_cotizacion_enviada;
    }
    loadStats().then(renderAllSiVisible).catch(() => {});
    return data.estado_conservado ? ' · estado del lead conservado' : data.ya_registrada ? ' · lead ya registrado' : ' · lead en COTIZACIÓN ENVIADA';
  } catch (e) {
    errToast(`${cbNumero(cot.numero)} se guardó; no se pudo registrar el lead. Reintenta «Registrar en lead» desde el historial.`);
    return ' · registro del lead pendiente';
  }
}
window.cbReintentarLead = async (id, btn) => {
  const c = cbFilas.get(id); if (!c || !c.lead_id) return;
  btn.disabled = true;
  try { await ensureVoucherLibs(); await cbPdfDe(c); const marca = await cbRegistrarLeadCot(c); if (!marca.includes('pendiente')) okToast(cbNumero(c.numero) + marca); }
  catch (_) { errToast('No se pudo generar el PDF. El estado del lead se conservó.'); }
  finally { btn.disabled = false; }
};
function cbDescargar(blob, nombre) { descargarArchivo(blob, nombre); }
window.cbVerPdf = async function cbVerPdf(id) {
  const c = cbFilas.get(id);
  if (!c) return;
  try {
    await ensureVoucherLibs();
    const blob = c.pdf_revision_path ? await DR.pdfVigente('cotizacion', c) : await cbPdfDe(c);
    window.open(URL.createObjectURL(blob), '_blank');
  } catch (e) { console.error('cbVerPdf', e); errToast('No se pudo generar el PDF'); }
};
window.cbReenviar = async function cbReenviar(id, btn) {
  if (DR && cbFilas.has(id)) { try { await DR.reenviarCotizacion(cbFilas.get(id)); } catch (e) { errToast(e.message); } return; }
  const c = cbFilas.get(id), asesorId = val('cb-asesor');
  if (!c) return;
  if (!asesorId) { errToast('Elige el asesor arriba, en «Enviar al asesor»'); document.getElementById('cb-asesor').focus(); return; }
  btn.disabled = true;
  try {
    await ensureVoucherLibs();
    if (asesorId === MI_USUARIO_ID) { cbDescargar(await cbPdfBlob(c), cbArchivo(c)); btn.disabled = false; return; }
    if (await cbEnviarAAsesor(c, await cbPdfBlob(c), asesorId)) {
      if (c.solicitud_id && MI_ES_AGENTE_BOLETERIA) await cbResolverSolicitud(c.solicitud_id, c);
      okToast(`${cbNumero(c.numero)} enviada a ${nombreUsuario(asesorId)}`); cbCargarHistorial(false);
    }
    else errToast('No se pudo enviar la cotización');
  } catch (e) { console.error('cbReenviar', e); errToast('No se pudo generar el PDF'); }
  finally { btn.disabled = false; }
};

// Mismo esquema que la Estimación de Zoho que reemplaza (QT-000464): logo,
// datos fiscales, "Facturar a", tabla de boletos, total, notas y términos.
async function cbPdfBlob(c) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });
  const W = 612, M = 40, oscuro = [60, 60, 60];
  try { doc.addImage(await cargarImagenBase64('logolotus-negro.png'), 'PNG', M - 8, 26, 84, 84); } catch (_e) { /* sin logo la cotización igual se genera */ }
  doc.setTextColor(20, 20, 20);
  doc.setFont('helvetica', 'bold'); doc.setFontSize(14);
  doc.text('DESTINO Y', M + 80, 62); doc.text('EVENTOS LOTUS 360', M + 80, 78);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(26);
  doc.text('Cotización', W - M, 66, { align: 'right' });
  doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text(`# ${cbNumero(c.numero)}`, W - M, 84, { align: 'right' });

  doc.setFontSize(9.5); doc.text('Destinos Y Eventos Lotus 360', M, 128);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); doc.setTextColor(70, 70, 70);
  ['J412935585  DESTINOS Y EVENTOS LOTUS 360, C.A', 'AV PRINCIPAL CC DINASTIA NIVEL 03 OF 54 SECTOR S/N', 'NAGUANAGUA CARABOBO ZONA POSTAL 2005']
    .forEach((l, i) => doc.text(l, M, 140 + i * 11));

  doc.setFontSize(9.5);
  doc.text('Fecha de la cotización:', W - M - 110, 196, { align: 'right' }); doc.text(cbFechaLarga(c.fecha), W - M, 196, { align: 'right' });
  if (c.vence) { doc.text('Válida hasta:', W - M - 110, 212, { align: 'right' }); doc.text(cbFechaLarga(c.vence), W - M, 212, { align: 'right' }); }
  doc.text('Facturar a', M, 204);
  doc.setFont('helvetica', 'bold'); doc.setTextColor(20, 20, 20);
  doc.text(doc.splitTextToSize(c.cliente.toUpperCase(), 260), M, 216);

  // Con niños o infantes el ítem lleva su descripción y una fila por categoría (adultos, niños, infantes).
  const filas = (c.items || []).flatMap((it, i) => {
    if (cbPorHabitacion(it)) return [[i + 1, cbDetalleCliente(it), cbHabitaciones(it).toFixed(2), cbMonto(cbImporte(it) / (cbHabitaciones(it) || 1)), cbMonto(cbImporte(it))]];
    if (!cbEsPax(it)) return [[i + 1, cbDetalle(it), Number(it.cant).toFixed(2), cbMonto(it.tarifa), cbMonto(cbImporte(it))]];
    if (it.tipo === 'hotel' && it.tramos?.length) return [[i + 1, cbDetalleCliente(it), '1.00', cbMonto(cbImporte(it)), cbMonto(cbImporte(it))]];
    // Hotel por noche: la columna Tarifa va por la estadía completa para que Cant. × Tarifa = Importe.
    const p = cbPax(it), noches = cbNochesCobro(it), tn = t => (Number(t) || 0) * noches;
    if (!p.n && !p.i) return [[i + 1, cbDetalle(it), p.a.toFixed(2), cbMonto(tn(it.tarifa)), cbMonto(cbImporte(it))]];
    const cat = [['ADULTOS', p.a, it.tarifa], ['NIÑOS', p.n, it.tarifa_nino], ['INFANTES', p.i, it.tarifa_infante]].filter(x => x[1])
      .map(([n, q, t]) => ['', cbPorNoche(it) ? `${n} · $${cbMonto(t)} × ${cbNochesTexto(noches).toUpperCase()}` : n, q.toFixed(2), cbMonto(tn(t)), cbMonto(q * tn(t))]);
    return [[i + 1, cbDetalle(it), '', '', ''], ...cat];
  });
  doc.autoTable({
    startY: 240, theme: 'plain', margin: { left: M, right: M },
    head: [['#', 'Artículo y descripción', 'Cant.', 'Tarifa', 'Importe']],
    body: filas,
    styles: { fontSize: 8.5, cellPadding: { top: 7, bottom: 7, left: 8, right: 8 }, textColor: [40, 40, 40], valign: 'top' },
    headStyles: { fillColor: oscuro, textColor: 255, fontStyle: 'normal', fontSize: 9.5 },
    columnStyles: { 0: { cellWidth: 30, halign: 'center' }, 2: { cellWidth: 52, halign: 'right' }, 3: { cellWidth: 70, halign: 'right' }, 4: { cellWidth: 80, halign: 'right' } },
    didParseCell: d => { if (d.section === 'head' && d.column.index >= 2) d.cell.styles.halign = 'right'; },
    didDrawCell: d => { if (d.section === 'body' && d.column.index === 0 && (!filas[d.row.index + 1] || filas[d.row.index + 1][0] !== '')) { doc.setDrawColor(190, 190, 190); doc.line(M, d.cell.y + d.cell.height, W - M, d.cell.y + d.cell.height); } },
  });

  let y = doc.lastAutoTable.finalY + 22;
  const total = `$${cbMonto(c.total)}`;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); doc.setTextColor(40, 40, 40);
  doc.text('Subtotal', W - M - 120, y, { align: 'right' }); doc.text(cbMonto(c.total), W - M - 8, y, { align: 'right' });
  y += 14;
  doc.setFillColor(243, 242, 240); doc.rect(W / 2 - 20, y, W / 2 + 20 - M, 32, 'F');
  doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
  doc.text('Total', W - M - 120, y + 20, { align: 'right' }); doc.text(total, W - M - 8, y + 20, { align: 'right' });
  y += 66;

  const bloque = (titulo, texto) => {
    if (!texto) return;
    if (y + 30 > 740) { doc.addPage(); y = 50; }
    doc.setFont('helvetica', 'normal'); doc.setFontSize(11); doc.setTextColor(40, 40, 40);
    doc.text(titulo, M, y); y += 16;
    doc.setFontSize(8.5); doc.setTextColor(60, 60, 60);
    const lineas = String(texto).split('\n').flatMap(l => l.trim() ? doc.splitTextToSize(l, W - 2 * M - 8).concat(['']) : ['']);
    lineas.forEach(l => { if (y > 740) { doc.addPage(); y = 50; } if (l) doc.text(l, M, y); y += l ? 11 : 5; });
    y += 14;
  };
  bloque('Notas', c.notas);
  bloque('Términos y condiciones', c.terminos);

  for (let p = 1; p <= doc.getNumberOfPages(); p++) {
    doc.setPage(p);
    doc.setDrawColor(200, 200, 200); doc.line(M, 752, W - M, 752);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(120, 120, 120);
    doc.text('Destino y Eventos Lotus 360 · 0241-5144470 / 0424-4634041 · Destinoyeventoslotus360@gmail.com', W / 2, 766, { align: 'center' });
  }
  drRotularPdf(doc, `Cotización ${cbNumero(c.numero)} · revisión ${c.revision || 1}`);
  return doc.output('blob');
}

// Cotización para el cliente (2026-10-15), con el estilo de exportarVentaPdf. La usa Lyra (lyraDatosPdf).
// datos = { cliente, titulo, fechas, personas, numero?, fecha?, opciones: [{ titulo, foto, precio_texto,
// lineas: [texto], tabla?: { filas: [[concepto, detalle, importe]], totales: [[etiqueta, valor]] } }],
// incluye, importante, notas: [texto], validez }. Los textos admiten *negrita* de WhatsApp.
async function pdfCotizacionCliente(datos) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });
  let F = 'helvetica', st = s => (s === 'normal' ? 'normal' : 'bold');
  try {
    (await cargarFuentesPdf()).forEach(([a, e, b]) => { doc.addFileToVFS(a, b); doc.addFont(a, 'Poppins', e); });
    F = 'Poppins'; st = s => s;
  } catch (_e) { /* sin Poppins sale en Helvetica */ }
  const C = { navy: [15, 23, 42], naranja: [234, 118, 22], ambar: [245, 158, 11], ambarOsc: [180, 83, 9], txt: [15, 23, 42], gris: [100, 116, 139], claro: [148, 163, 184], linea: [226, 232, 240], suave: [248, 250, 252], blanco: [255, 255, 255] };
  const tinte = (rgb, k) => rgb.map(c => Math.round(c + (255 - c) * k));
  const font = (s, size, rgb) => { doc.setFont(F, st(s)); doc.setFontSize(size); doc.setTextColor(...rgb); };
  const plano = s => pdfSinEmojis(s).replace(/\*/g, '');
  const X0 = 40, X1 = 572, W = X1 - X0, YMAX = 730;
  // Foto: siempre el derivado 640 del Worker, nunca el original de Supabase (incidente de egress).
  // cache 'reload': un <img> previo pudo dejar en caché la misma URL sin cabecera CORS.
  const cargarFoto = async url => {
    if (!url?.startsWith(CDN_FOTOS)) return null;
    const r = await fetch(url.replace(/\/_d\/\d+\//, '/_d/640/'), { cache: 'reload' });
    const tipo = (r.headers.get('content-type') || '').split(';')[0];
    const fmt = { 'image/jpeg': 'JPEG', 'image/png': 'PNG' }[tipo];
    if (!r.ok || !fmt) return null;
    const src = `data:${tipo};base64,` + bytesABase64(new Uint8Array(await r.arrayBuffer()));
    const { width: w, height: h } = doc.getImageProperties(src);
    return { src, fmt, w, h };
  };
  const opciones = (datos.opciones || []).filter(o => o && (o.titulo || o.tabla));
  const fotos = await Promise.all(opciones.map(o => cargarFoto(o.foto).catch(() => null)));
  const emitida = (datos.fecha ? new Date(datos.fecha.slice(0, 10) + 'T12:00:00') : new Date())
    .toLocaleDateString('es-VE', { timeZone: 'America/Caracas', day: 'numeric', month: 'long', year: 'numeric' });

  doc.setFillColor(...C.navy); doc.rect(0, 0, 612, 112, 'F');
  doc.setFillColor(...C.naranja); doc.rect(0, 112, 612, 3, 'F');
  doc.setFillColor(...C.ambar); doc.rect(0, 112, 190, 3, 'F');
  doc.setFillColor(...C.blanco); doc.circle(X0 + 34, 56, 34, 'F');
  try { doc.addImage(await cargarImagenBase64('logolotus-negro.png'), 'PNG', X0 + 4, 26, 60, 60); } catch (_e) { /* sin logo igual sale */ }
  font('bold', 15, C.blanco); doc.text('Destino y Eventos', 122, 50);
  font('bold', 15, C.naranja); doc.text('Lotus 360', 122, 69);
  font('normal', 8.5, C.claro); doc.text('Agencia de viajes · destinoyeventoslotus360.com', 122, 85);
  font('medium', 7.5, C.claro); doc.text('COTIZACIÓN DE VIAJE', X1, 44, { align: 'right', charSpace: 1.4 });
  if (datos.numero) {
    font('bold', 24, C.blanco); doc.text(`N° ${datos.numero}`, X1, 74, { align: 'right' });
    font('normal', 8.5, C.claro); doc.text(emitida, X1, 90, { align: 'right' });
  } else { font('bold', 16, C.blanco); doc.text(emitida, X1, 70, { align: 'right' }); }

  let y = 150;
  const salto = alto => { if (y + alto > YMAX) { doc.addPage(); y = 56; } };
  const seccion = (t, alto = 24) => {
    salto(34 + alto);
    font('semibold', 8.5, C.naranja); doc.text(t.toUpperCase(), X0, y, { charSpace: 1 });
    doc.setDrawColor(...C.linea); doc.setLineWidth(0.8); doc.line(X0, y + 7, X1, y + 7);
    y += 26;
  };
  // Texto con *negrita*: palabra por palabra, partiendo renglones a mano (jsPDF no mezcla fuentes en un text()).
  const parrafo = (txt, x, w, size, rgb) => {
    const lh = size * 1.45;
    const piezas = pdfSinEmojis(txt).split(/(\*[^*\n]+\*)/).filter(Boolean).flatMap(p => {
      const b = /^\*[^*]+\*$/.test(p);
      return (b ? p.slice(1, -1) : p.replace(/\*/g, '')).split(/(\s+)/).filter(Boolean).map(t => [t, b]);
    });
    let cx = x;
    salto(lh);
    piezas.forEach(([t, b]) => {
      font(b ? 'semibold' : 'normal', size, b ? C.txt : rgb);
      const tw = doc.getTextWidth(t);
      if (!t.trim()) { if (cx > x) cx += tw; return; }
      if (cx + tw > x + w && cx > x) { y += lh; cx = x; salto(lh); }
      doc.text(t, cx, y); cx += tw;
    });
    y += lh;
  };
  const vineta = (txt, x, w, size, rgb) => {
    salto(size * 1.45);
    doc.setFillColor(...C.naranja); doc.circle(x + 2.5, y - size * 0.33, 1.8, 'F');
    parrafo(txt, x + 11, w - 11, size, rgb);
  };

  seccion('Su viaje');
  if (datos.titulo) { font('bold', 15, C.txt); doc.splitTextToSize(plano(datos.titulo), W).forEach(l => { doc.text(l, X0, y); y += 19; }); y += 6; }
  const campos = [['Cliente', datos.cliente], ['Fechas', datos.fechas], ['Personas', datos.personas]].filter(([, v]) => v);
  if (campos.length) {
    const cw = W / campos.length;
    let alto = 0;
    campos.forEach(([k, v], i) => {
      const x = X0 + i * cw;
      font('medium', 7.5, C.gris); doc.text(k.toUpperCase(), x, y, { charSpace: 0.6 });
      font('semibold', 10.5, C.txt);
      const ls = doc.splitTextToSize(plano(v), cw - 16).slice(0, 3);
      ls.forEach((l, j) => doc.text(l, x, y + 16 + j * 14));
      alto = Math.max(alto, 16 + ls.length * 14);
    });
    y += alto + 8;
  }

  opciones.forEach((o, i) => {
    const foto = fotos[i], fw = 196, fh = 136;
    y += 8;
    seccion(opciones.length > 1 ? `Opción ${i + 1}` : 'Detalle', foto ? fh : 60);
    const y0 = y - 8, tx = foto ? X0 + fw + 18 : X0, tw = X1 - tx;
    if (foto) {
      // "Cover": la foto llena el recuadro redondeado y se recorta lo que sobra.
      const k = Math.max(fw / foto.w, fh / foto.h), dw = foto.w * k, dh = foto.h * k;
      doc.saveGraphicsState();
      doc.roundedRect(X0, y0, fw, fh, 10, 10, null); doc.clip(); doc.discardPath();
      doc.addImage(foto.src, foto.fmt, X0 + (fw - dw) / 2, y0 + (fh - dh) / 2, dw, dh);
      doc.restoreGraphicsState();
    }
    y = y0 + 14;
    font('bold', 13, C.txt); doc.splitTextToSize(plano(o.titulo), tw).forEach(l => { doc.text(l, tx, y); y += 17; });
    if (o.precio_texto) { font('semibold', 10.5, C.naranja); doc.splitTextToSize(plano(o.precio_texto), tw).forEach(l => { doc.text(l, tx, y); y += 15; }); }
    y += 4;
    (o.lineas || []).forEach(l => vineta(l, tx, tw, 9.5, C.gris));
    if (foto) y = Math.max(y, y0 + fh + 16);
    if (o.tabla?.filas?.length) {
      salto(70);
      doc.autoTable({
        startY: y, theme: 'plain', margin: { left: X0, right: 612 - X1, top: 56, bottom: 792 - YMAX },
        head: [['Concepto', 'Detalle', 'Subtotal']],
        body: o.tabla.filas.map(r => r.map(plano)),
        styles: { font: F, fontStyle: st('normal'), fontSize: 8.5, textColor: C.txt, cellPadding: { top: 6, bottom: 6, left: 8, right: 8 }, valign: 'top' },
        headStyles: { fillColor: C.navy, textColor: 255, fontStyle: st('semibold'), fontSize: 8 },
        alternateRowStyles: { fillColor: C.suave },
        columnStyles: { 0: { cellWidth: 150, fontStyle: st('medium') }, 1: { textColor: C.gris }, 2: { cellWidth: 84, halign: 'right', fontStyle: st('semibold') } },
        didParseCell: d => { if (d.section === 'head' && d.column.index === 2) d.cell.styles.halign = 'right'; },
      });
      y = doc.lastAutoTable.finalY;
      (o.tabla.totales || []).forEach(([k, v]) => {
        salto(28);
        doc.setFillColor(...tinte(C.ambar, 0.86)); doc.rect(X0, y, W, 26, 'F');
        font('semibold', 9, C.ambarOsc); doc.text(plano(k).toUpperCase(), X1 - 110, y + 17, { align: 'right', charSpace: 0.6 });
        font('bold', 12.5, C.txt); doc.text(plano(v), X1 - 8, y + 17.5, { align: 'right' });
        y += 26;
      });
      y += 10;
    }
  });

  if (datos.incluye) { y += 6; seccion('Incluye'); parrafo(datos.incluye, X0, W, 9.5, C.gris); }
  if (datos.importante) {
    y += 10;
    font('normal', 9, C.txt);
    const ls = doc.splitTextToSize(plano(datos.importante), W - 34), alto = 30 + ls.length * 13;
    salto(alto);
    doc.setFillColor(...tinte(C.ambar, 0.88)); doc.roundedRect(X0, y, W, alto, 6, 6, 'F');
    doc.setFillColor(...C.ambar); doc.rect(X0, y, 4, alto, 'F');
    font('semibold', 8, C.ambarOsc); doc.text('IMPORTANTE', X0 + 18, y + 16, { charSpace: 1 });
    font('normal', 9, C.txt); ls.forEach((l, j) => doc.text(l, X0 + 18, y + 31 + j * 13));
    y += alto + 16;
  }
  if (datos.notas?.length) {
    y += 6; seccion('Detalles');
    datos.notas.forEach(n => /^[•\-–]\s*/.test(n) ? vineta(n.replace(/^[•\-–]\s*/, ''), X0, W, 9.5, C.gris) : parrafo(n, X0, W, 9.5, C.gris));
  }
  if (datos.validez) { y += 10; parrafo(datos.validez, X0, W, 8.5, C.gris); }

  const n = doc.getNumberOfPages();
  for (let p = 1; p <= n; p++) {
    doc.setPage(p);
    doc.setDrawColor(...C.linea); doc.setLineWidth(0.8); doc.line(X0, 752, X1, 752);
    font('normal', 7.5, C.gris);
    doc.text('Destino y Eventos Lotus 360 · 0241-5144470 / 0424-4634041 · Destinoyeventoslotus360@gmail.com', X0, 766);
    if (n > 1) doc.text(`${p} / ${n}`, X1, 766, { align: 'right' });
  }
  drRotularPdf(doc, `Cotización ${datos.numero} · revisión ${datos.revision || 1}`);
  return doc.output('blob');
}

/* ---------- Realtime ---------- */
// Salud del canal (falla #2 del plan de rediseño): sin esto el websocket
// puede morir en silencio y la interfaz sigue pareciendo viva. El indicador
// (#leads-live-dot / #leads-live-status) es honesto: verde solo mientras el
// canal está realmente SUBSCRIBED, gris con leyenda apenas se cae.
let canalLeadsLive = null, intentosReconexionLive = 0, timerReconexionLive = null, cerrandoCanalIntencional = false;
function marcarLeadsLiveVivo() {
  intentosReconexionLive = 0;
  clearTimeout(timerReconexionLive);
  const dot = document.getElementById('leads-live-dot'), status = document.getElementById('leads-live-status');
  if (dot) dot.className = 'live-dot vivo';
  if (status) status.textContent = '';
}
function marcarLeadsLiveCaido() {
  const dot = document.getElementById('leads-live-dot'), status = document.getElementById('leads-live-status');
  if (dot) dot.className = 'live-dot caido';
  if (status) status.textContent = 'Sin conexión en vivo';
}
function reconectarLeadsLive(inmediato = false) {
  clearTimeout(timerReconexionLive);
  const espera = inmediato ? 0 : Math.min(60000, 2000 * (2 ** intentosReconexionLive));
  if (!inmediato) intentosReconexionLive++;
  timerReconexionLive = setTimeout(() => {
    cerrandoCanalIntencional = true;
    const viejos = [canalLeadsLive, canalCorreosLive].filter(Boolean);
    canalLeadsLive = canalCorreosLive = null;
    viejos.forEach(c => sb.removeChannel(c).catch(() => {}));
    cerrandoCanalIntencional = false;
    subscribeRealtime();
  }, espera);
}
window.addEventListener('online', () => { intentosReconexionLive = 0; reconectarLeadsLive(true); });
window.addEventListener('offline', marcarLeadsLiveCaido);

// Topic con sufijo propio por suscripción: removeChannel es asíncrono y sb.channel() con el
// mismo nombre devolvía el canal viejo aún cerrándose (bindings duplicados o canal muerto).
let canalCorreosLive = null, nCanalLive = 0;
function subscribeRealtime() {
  const n = ++nCanalLive;
  const canal = canalLeadsLive = sb.channel('leads-live-' + n);
  canal
    .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'leads' }, payload => {
      // Mismo criterio de visibilidad que buildQuery (:2334) -- si no, avisa
      // de leads que el usuario nunca ve aparecer en la lista. Nota: buildQuery
      // NO excluye es_prueba (esos leads sí aparecen, con su chip), así que acá
      // tampoco se filtra por es_prueba -- solo lo que buildQuery de verdad excluye.
      if (payload.new.servicio !== SERVICIO_POSADA_IA && !payload.new.eliminado_at && !payload.new.contacto_directo_enviado_at) toast(payload.new);
      loadStats().then(renderAllSiVisible);
      if (page === 1 && document.getElementById('sec-leads')?.classList.contains('active')) encolarLeadLive(payload);
      // Solo empujar al inbox en vivo si el lead realmente llegó sin atender
      // -- un INSERT no siempre significa "nuevo por atender" (ej. import
      // masivo con estado ya PAGO REALIZADO, hallazgo real 2026-07-24: sin
      // este chequeo, cualquier INSERT terminaba en el inbox del asesor con
      // botón Atender aunque la venta ya estuviera cerrada).
      if (ROL === 'asesor' && payload.new.estado === 'POR ATENDER' && !payload.new.fecha_primer_contacto && !payload.new.contacto_directo_enviado_at) recibirLeadNuevoInbox(payload.new);
    })
    // RLS ya filtra este evento a leads propios -- si uno deja de estar
    // pendiente por otra vía (ej. lo editan a mano en el drawer/tabla), sale
    // del inbox sin esperar un refresh manual.
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'leads' }, payload => {
      if (ROL === 'asesor' && INBOX_LEADS.some(x => x.id === payload.new.id)
          && (payload.new.estado !== 'POR ATENDER' || payload.new.fecha_primer_contacto || payload.new.eliminado_at)) quitarDeInbox(payload.new.id);
      // Solo ventas, con debounce y sin esqueleto: cada UPDATE de cualquier lead
      // (el bot escribe sin parar) recargaba la pestaña Reservas entera.
      if (payload.new.estado === 'PAGO REALIZADO' && document.getElementById('sec-postventa')?.classList.contains('active')) {
        clearTimeout(PV_RT_TIMER); PV_RT_TIMER = setTimeout(() => loadPostventa(true), 5000);
      }
      // A diferencia del INSERT (siempre entra en página 1 por el order by
      // fecha_creacion desc), un UPDATE puede tocar un lead de cualquier
      // página -- se refresca igual, loadTable() ya respeta filtros/página
      // actuales así que si el lead editado no está en la vista no cambia nada.
      if (document.getElementById('sec-leads')?.classList.contains('active')) encolarLeadLive(payload);
    })
    .subscribe(estado => {
      if (estado === 'SUBSCRIBED') { marcarLeadsLiveVivo(); return; }
      if (cerrandoCanalIntencional || canal !== canalLeadsLive) return;
      if (['CHANNEL_ERROR', 'TIMED_OUT', 'CLOSED'].includes(estado)) { marcarLeadsLiveCaido(); reconectarLeadsLive(); }
    });

  // Correo (Fase 1 del cliente Gmail): sin backoff propio como leads-live --
  // canal chico, mismo criterio simple que mensajes-badge. RLS ya filtra qué
  // correos llegan a este cliente. Refresca la bandeja si está a la vista, y
  // la pestaña de correo del lead abierto si el correo nuevo es de ese lead.
  canalCorreosLive = sb.channel('gmail-correos-live-' + n).on('postgres_changes', { event: '*', schema: 'public', table: 'gmail_correos' }, payload => {
    programarRecargaCorreo();
    if (currentLead && payload.new?.lead_id === currentLead.id) { CORREO_LEAD_CACHE = null; cargarCorreoLead(currentLead); }
  }).subscribe();
}

// Resync al volver de segundo plano (falla #3): el socket pudo morir sin
// avisar mientras el teléfono estaba bloqueado, y Realtime no reenvía lo
// perdido. Se refresca todo lo que dependía del canal caído -- KPIs/
// pipeline, inbox+badge, la tabla si está a la vista -- y se reintenta la
// suscripción de una vez, sin esperar a que algo falle para notarlo.
// Con throttle: el asesor salta a WhatsApp y vuelve todo el tiempo, y cada regreso
// repintaba lista, KPIs e inbox y tiraba el canal aunque siguiera vivo (lag + parpadeo).
// El canal solo se rearma si no está unido o si la app estuvo oculta más de 2 min.
let ultimoResync = 0, ocultoDesde = 0;
function resyncTrasSegundoPlano() {
  const fuera = ocultoDesde ? Date.now() - ocultoDesde : 0;
  ocultoDesde = 0;
  if (Date.now() - ultimoResync < 30000) return Promise.resolve();
  ultimoResync = Date.now();
  const p = loadStats().then(renderAllSiVisible);
  if (ROL === 'asesor') loadInboxLeads();
  if (document.getElementById('sec-leads')?.classList.contains('active')) loadTable(true);
  if (fuera > 120000 || canalLeadsLive?.state !== 'joined') reconectarLeadsLive(true);
  return p;
}
document.addEventListener('visibilitychange', () => { if (document.hidden) ocultoDesde = Date.now(); else resyncTrasSegundoPlano(); });
// Red de seguridad si el websocket de Realtime se cae y tarda en reconectar
// -- refresco silencioso de la tabla mientras la sección Leads esté abierta,
// se arranca/para desde activateSection() para no dejarlo corriendo en fondo.
//
// Cada refresco cuesta 45 KB (`select('*')` = 52 columnas × 25 filas) y no se
// puede recortar sin romper la ficha: `openDrawer(l)` recibe el objeto entero.
// A 50 s eran 72 refrescos por hora POR USUARIO, y como el timer solo miraba la
// sección visible y no `document.hidden`, seguía corriendo con la PWA abierta en
// segundo plano en el teléfono de cada asesor -- toda la noche incluida. Medido:
// ~200 MB/día entre los 7 usuarios, sobre una cuota de 5 GB al mes.
//
// Realtime ya cubre el caso normal (INSERT/UPDATE llegan al instante); esto solo
// existe para cuando el websocket se cae. 3 minutos alcanza de sobra para eso, y
// el `visibilitychange` recupera la frescura apenas alguien vuelve a mirar --
// mismo patrón que `setupLatidoPresencia`.
let leadsPollInterval = null;
const leadsVisible = () => !document.hidden && document.getElementById('sec-leads').classList.contains('active');
function iniciarPollLeads() {
  if (leadsPollInterval) return;
  leadsPollInterval = setInterval(() => { if (leadsVisible()) loadTable(true); }, 180000);
}
function detenerPollLeads() { clearInterval(leadsPollInterval); leadsPollInterval = null; }
// Card nueva al tope del inbox en vivo + notificación local instantánea si la
// pestaña no está en foco (no depende de la latencia del push del servidor).
function recibirLeadNuevoInbox(lead) {
  INBOX_LEADS.unshift(lead);
  renderInbox();
  const card = document.querySelector(`.inbox-card[data-id="${lead.id}"]`);
  if (card) { card.classList.add('inbox-new'); setTimeout(() => card.classList.remove('inbox-new'), 2200); }
  // showNotification() vía SW, no `new Notification(...)` -- ese constructor
  // directo tira "Illegal constructor" en Chrome/Android cuando corre como
  // PWA instalada (la forma en que la usan los asesores), no solo en sitios
  // sueltos de escritorio.
  if (MI_PREFERENCIAS.notificaciones_leads !== false && document.hidden && typeof Notification !== 'undefined' && Notification.permission === 'granted' && navigator.serviceWorker) {
    navigator.serviceWorker.ready.then(reg => reg.showNotification('Nuevo lead — ' + (lead.destino || 'sin destino'), {
      body: `${lead.nombre} · contacto disponible al tomarlo en el CRM`, icon: './icons/icon-192.png', badge: './icons/badge-72.png', tag: `lead-${lead.id}`,
    }));
  }
}
function toast(l) { const t = document.createElement('div'); t.className = 'toast'; t.innerHTML = `<i class="fas fa-bolt"></i> <div><b>Nuevo lead en vivo</b><br>${esc(l.nombre)} · ${esc(l.destino || '')}</div>`; document.getElementById('toasts').appendChild(t); setTimeout(() => t.classList.add('show'), 30); setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, 5200); }
function okToast(msg) { const t = document.createElement('div'); t.className = 'toast'; t.innerHTML = `<i class="fas fa-check"></i> <div><b>${esc(msg)}</b></div>`; document.getElementById('toasts').appendChild(t); setTimeout(() => t.classList.add('show'), 30); setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, 3500); }
function errToast(msg) { const t = document.createElement('div'); t.className = 'toast toast-err'; t.innerHTML = `<i class="fas fa-triangle-exclamation"></i> <div><b>${esc(msg)}</b></div>`; document.getElementById('toasts').appendChild(t); setTimeout(() => t.classList.add('show'), 30); setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, 5000); }

// `sb.functions.invoke` con status != 2xx deja `data=null` y el cuerpo JSON
// real (el { ok:false, error } que arma la Edge Function) adentro de
// `error.context`, un Response sin leer -- sin esto, cualquier toast de
// error de una función queda pelado ("No se pudo X: ") porque `data?.error`
// es null. Lee el context si existe, si no cae al mensaje genérico de error.
async function msgErrorFn(error, data) {
  if (data?.error) return data.error;
  const ctx = error?.context;
  if (ctx && typeof ctx.json === 'function') {
    try { const body = await ctx.clone().json(); if (body?.error) return body.error; } catch {}
  }
  return error?.message || 'error desconocido';
}
// Igual que okToast/errToast pero con HTML propio (nunca de input de usuario)
// y más tiempo en pantalla -- para acciones que el asesor tiene que tocar,
// como el link de WhatsApp cuando window.open() vuelve bloqueado.
function linkToast(html) { const t = document.createElement('div'); t.className = 'toast'; t.innerHTML = `<i class="fas fa-link"></i> <div>${html}</div>`; document.getElementById('toasts').appendChild(t); setTimeout(() => t.classList.add('show'), 30); setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, 10000); }

/* ---------- Historial interno (gesto de "atrás" del SO no debe salir de la PWA) ----------
   Cada cambio de sección o apertura de overlay (drawer/lightbox/sheet) empuja
   una entrada de historial. El botón/gesto de atrás de Android y el
   swipe-back de iOS disparan `popstate` en vez de salir de la app mientras
   haya algo en NAV_STACK — al vaciarse (pantalla raíz), el siguiente atrás
   sí sale de la PWA (comportamiento estándar, no se intercepta más allá). */
let NAV_STACK = [];
function navPush(entry) { NAV_STACK.push(entry); history.pushState({ navDepth: NAV_STACK.length }, ''); }
// Usado por los cierres propios de la UI (botón X, backdrop, "Listo") para
// consumir la entrada de historial que ese overlay había empujado — sin
// esto, cada cierre manual deja una entrada fantasma y el próximo gesto de
// atrás del sistema queda desfasado (hay que tocarlo dos veces sin efecto).
function navConsume() { if (NAV_STACK.length) history.back(); }
// Saca la entrada sin tocar el historial: para cerrar algo justo antes de navegar a otra pantalla.
function navQuitar(entry) { const i = NAV_STACK.indexOf(entry); if (i >= 0) NAV_STACK.splice(i, 1); }
window.addEventListener('popstate', () => {
  if (!NAV_STACK.length) return; // pantalla raíz: se deja que el SO cierre la PWA
  const top = NAV_STACK.pop();
  if (top.type === 'drawer') window.closeDrawer(true);
  else if (top.type === 'lightbox') closeLightbox(true);
  else if (top.type === 'tutorial') cerrarTutorial(true);
  else if (top.type === 'tar-comparar') tarCerrarComparador(true);
  else if (top.type === 'sheet') closeSheet(top.id, true);
  else if (top.type === 'chat-panel') chatAtrasSistema();
  else if (top.type === 'wa-conv') waCerrarChat(true);
  else if (top.type === 'dm-conv') dmCerrarChat(true);
  else if (top.type === 'section') activateSection(top.prevSec, true);
  else if (top.type === 'tour') volverAlMenuTutorial(true);
  else if (top.type === 'menu') cerrarMenuMovil('fromNav');
  else if (top.type === 'seleccion') top.limpiar?.();
  else if (top.type === 'tk-panel') top.cerrar?.();
  else if (top.type === 'lyra') lyraCerrar(true);
});

/* ---------- Nav ---------- */
let currentSec = null;
// Qué secciones pasaron por activateSection() al menos una vez -- el peek
// del swipe (Fase 5.2) lo consulta para no asomar una sección que nunca
// disparó su carga perezosa (loadTarifario, loadFacturacion, etc): montar
// 500 filas a mitad de gesto se siente peor que no tener peek.
const SECCIONES_CARGADAS = new Set();
// Secciones que se retiraron del menú (2026-07-27) y a dónde fue su contenido.
// Sin esto, quien tenía guardada una de ellas como última sección abría el CRM
// contra un id que ya no existe y reventaba en el getElementById de abajo.
const SECCIONES_REUBICADAS = {
  metricas: 'gestion-personal',
  reasignaciones: 'gestion-personal',
  'leads-colaboraciones': 'leads',
  'leads-fallidos': 'gestion-personal',
  'buscar-tarifario': 'tarifario',
  extractor: 'leads',
  // "Mis leads" del rol asesor_prueba, fusionado en asesor (2026-08-19).
  'leads-prueba': 'clientes-asignados',
};
async function loadClientesAsignados() {
  const wrap = document.getElementById('clientes-asignados-list');
  if (!wrap) return;
  const { data, error } = await sb.rpc('listar_mis_clientes_asignados');
  if (error) { console.error(error); wrap.innerHTML = '<div class="es-s">No se pudieron cargar tus clientes.</div>'; return; }
  const filas = data || [];
  if (!filas.length) { wrap.innerHTML = '<div class="es-s">No tenés clientes asignados por ahora.</div>'; return; }
  wrap.innerHTML = filas.map(l => `<article class="entity-card"><div class="ec-head"><b>${esc(l.nombre || 'Sin nombre')}</b><span class="chip">${esc(l.estado || 'Sin estado')}</span></div><div class="ec-row"><i class="fas fa-phone"></i> ${esc(l.telefono || 'Sin teléfono')}</div><div class="ec-row"><i class="fas fa-location-dot"></i> ${esc(l.destino || 'Sin destino')}</div><div class="ec-row"><i class="fas fa-clock"></i> ${l.vence_at ? esc(fmtFechaHoraCaracas(l.vence_at)) : 'Sin plazo'}</div>${l.notas ? `<div class="ec-row"><i class="fas fa-note-sticky"></i> ${esc(l.notas)}</div>` : ''}<div class="seg-group" style="margin-top:10px;flex-wrap:wrap"><button class="seg" data-r="no_contesta" data-task="${l.task_id}">No contesta</button><button class="seg" data-r="numero_equivocado" data-task="${l.task_id}">Número equivocado</button><button class="seg" data-r="no_interesa" data-task="${l.task_id}">No interesa</button><button class="seg" data-r="interesado" data-task="${l.task_id}">Interesado</button><button class="seg" data-r="ya_viajo" data-task="${l.task_id}">Ya viajó</button></div><textarea class="ei" data-nota placeholder="¿Qué te dijo el cliente? (obligatorio para registrar el resultado)"></textarea><div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap"><button class="btn-sm" data-editar-lead="${l.lead_id}"><i class="fas fa-pen"></i> Editar datos</button><a class="btn-sm" href="https://wa.me/${esc(String(l.telefono || '').replace(/\D/g,''))}" target="_blank" rel="noopener"><i class="fab fa-whatsapp"></i> WhatsApp</a><a class="btn-sm" href="tel:${esc(l.telefono || '')}"><i class="fas fa-phone"></i> Llamar</a></div></article>`).join('');
  wrap.querySelectorAll('[data-r]').forEach(btn => btn.addEventListener('click', async () => {
    const nota = btn.closest('.entity-card').querySelector('[data-nota]').value.trim();
    if (!nota) { errToast('Contá qué te dijo el cliente antes de registrar el resultado.'); return; }
    btn.disabled = true;
    const { data: r, error: e } = await sb.rpc('registrar_contacto_lead', { p_task_id: Number(btn.dataset.task), p_resultado: btn.dataset.r, p_nota: nota });
    if (e || !r?.ok) { errToast('No se pudo registrar el contacto.'); btn.disabled = false; return; }
    okToast('Contacto registrado');
    // Una objeción recién escuchada es justo lo que conviene guardar para
    // repasar: se ofrece pasarla a Mis Notas sin volver a escribirla.
    if (btn.dataset.r === 'no_interesa' && await confirmarSheet({
      titulo: '¿Guardar esta objeción en Mis Notas?',
      detalle: 'Te la vamos a recordar cada tanto para que tengas lista la respuesta.',
      textoOk: 'Guardar nota'
    })) { window.guardarComoNota('Objeción: ' + (btn.closest('.entity-card')?.querySelector('.ec-head b')?.textContent || 'cliente'), nota, ['objeciones']); return; }
    loadClientesAsignados();
  }));
  // Editar los datos del cliente reusa el MISMO drawer de la sección Leads
  // (openDrawer/guardarLead) -- no hay un segundo formulario que mantener.
  wrap.querySelectorAll('[data-editar-lead]').forEach(btn => btn.addEventListener('click', async () => {
    const { data: lead, error: e } = await sb.from('leads').select('*').eq('id', Number(btn.dataset.editarLead)).single();
    if (e || !lead) { errToast('No se pudo cargar el cliente'); return; }
    openDrawer(lead);
  }));
  entradaLista(wrap);
}

/* ---------- Mis Notas (libreta propia del asesor, con repaso espaciado) ---------- */
// El repaso lo decide el backend (repasar_nota): acá solo se muestra y se
// reporta si acertó o no. Los intervalos viven en la migración, no duplicados acá.
let NOTAS_FILTRO_ETIQUETA = null;
let NOTAS_BUSQUEDA = '';

async function loadMisNotas() {
  await Promise.all([cargarNotasRepaso(), cargarListaNotas()]);
}

async function cargarNotasRepaso() {
  const card = document.getElementById('notas-repaso-card');
  const wrap = document.getElementById('notas-repaso-list');
  if (!card || !wrap) return;
  const { data, error } = await sb.rpc('notas_para_repasar_hoy');
  if (error) console.error(error);
  const pendientes = error ? [] : (data || []);
  actualizarBadgeNotas(pendientes.length);
  if (!pendientes.length) { card.style.display = 'none'; return; }
  card.style.display = '';
  wrap.innerHTML = pendientes.map(n => `<article class="entity-card" data-nota-repaso="${n.id}">
    <div class="ec-head"><b>${esc(n.titulo)}</b><span class="chip">Nivel ${n.nivel}</span></div>
    <div class="ec-row nota-respuesta" style="display:none;white-space:pre-wrap">${esc(n.cuerpo)}</div>
    <div class="tbar" style="margin-top:10px;flex-wrap:wrap">
      <button class="btn-sm" data-nota-ver="${n.id}"><i class="fas fa-eye"></i> Ver respuesta</button>
      <button class="btn-sm" data-nota-acerte="${n.id}"><i class="fas fa-check"></i> Ya me lo sé</button>
      <button class="btn-sm" data-nota-falle="${n.id}"><i class="fas fa-rotate-left"></i> Todavía me cuesta</button>
    </div>
  </article>`).join('');
  entradaLista(wrap);
  wrap.querySelectorAll('[data-nota-ver]').forEach(b => b.addEventListener('click', () => {
    const cuerpo = b.closest('.entity-card').querySelector('.nota-respuesta');
    cuerpo.style.display = cuerpo.style.display === 'none' ? '' : 'none';
  }));
  wrap.querySelectorAll('[data-nota-acerte],[data-nota-falle]').forEach(b => b.addEventListener('click', async () => {
    const id = b.dataset.notaAcerte || b.dataset.notaFalle;
    b.disabled = true;
    const { data: r, error: e } = await sb.rpc('repasar_nota', { p_id: id, p_acerte: !!b.dataset.notaAcerte });
    if (e || !r?.ok) { errToast('No se pudo registrar el repaso.'); b.disabled = false; return; }
    okToast(b.dataset.notaAcerte ? `Bien. Vuelve el ${fmtFechaCorta(r.proximo_repaso)}` : 'Listo, te lo repito mañana');
    await loadMisNotas();
  }));
}

const fmtFechaCorta = iso => { try { return new Date(iso + 'T12:00:00').toLocaleDateString('es-VE', { day: 'numeric', month: 'short' }); } catch { return iso; } };

async function cargarListaNotas() {
  const wrap = document.getElementById('notas-list');
  if (!wrap) return;
  const { data, error } = await sb.rpc('listar_mis_notas', { p_etiqueta: NOTAS_FILTRO_ETIQUETA, p_busqueda: NOTAS_BUSQUEDA || null });
  if (error) { console.error(error); wrap.innerHTML = '<div class="es-s">No se pudieron cargar tus notas.</div>'; return; }
  const notas = data || [];
  renderChipsEtiquetasNotas(notas);
  if (!notas.length) {
    wrap.innerHTML = (NOTAS_FILTRO_ETIQUETA || NOTAS_BUSQUEDA)
      ? '<div class="es-s">Ninguna nota coincide con ese filtro.</div>'
      : '<div class="es-s">Todavía no tenés notas. Empezá por eso que siempre se te olvida.</div>';
    return;
  }
  wrap.innerHTML = notas.map(n => `<article class="entity-card">
    <div class="ec-head"><b>${esc(n.titulo)}</b>${n.me_cuesta ? '<span class="chip am">Me cuesta</span>' : ''}</div>
    <div class="ec-row" style="white-space:pre-wrap">${esc(n.cuerpo)}</div>
    ${n.etiquetas?.length ? `<div class="chip-group" style="margin-top:8px">${n.etiquetas.map(e => `<span class="chip">${esc(e)}</span>`).join('')}</div>` : ''}
    ${n.me_cuesta && n.proximo_repaso ? `<div class="ec-row"><i class="fas fa-rotate-right"></i> Próximo repaso: ${esc(fmtFechaCorta(n.proximo_repaso))}</div>` : ''}
    <div class="tbar" style="margin-top:10px">
      <button class="btn-sm" data-nota-editar="${n.id}"><i class="fas fa-pen"></i> Editar</button>
      <button class="btn-sm" data-nota-borrar="${n.id}"><i class="fas fa-trash"></i> Borrar</button>
    </div>
  </article>`).join('');
  entradaLista(wrap);
  wrap.querySelectorAll('[data-nota-editar]').forEach(b => b.addEventListener('click', () => {
    abrirEditorNota(notas.find(n => n.id === b.dataset.notaEditar));
  }));
  wrap.querySelectorAll('[data-nota-borrar]').forEach(b => b.addEventListener('click', async () => {
    if (!(await confirmarSheet({ titulo: '¿Borrar esta nota?', detalle: 'No se puede deshacer.', textoOk: 'Borrar' }))) return;
    const { data: r, error: e } = await sb.rpc('borrar_nota', { p_id: b.dataset.notaBorrar });
    if (e || !r?.ok) { errToast('No se pudo borrar.'); return; }
    okToast('Nota borrada'); await loadMisNotas();
  }));
}

// Las etiquetas del filtro salen de las notas ya cargadas: sin filtro activo la
// lista es completa, así que sirve como universo. Con un filtro puesto se
// conserva el chip activo aunque quede fuera del resultado.
let NOTAS_ETIQUETAS_CONOCIDAS = [];
function renderChipsEtiquetasNotas(notas) {
  if (!NOTAS_FILTRO_ETIQUETA) {
    NOTAS_ETIQUETAS_CONOCIDAS = [...new Set(notas.flatMap(n => n.etiquetas || []))].sort();
  }
  renderChipGroup('notas-etiquetas-chips',
    NOTAS_ETIQUETAS_CONOCIDAS.map(e => ({ valor: e, etiqueta: e })),
    {
      multi: false,
      seleccion: NOTAS_FILTRO_ETIQUETA ? [NOTAS_FILTRO_ETIQUETA] : [],
      onChange: vals => { NOTAS_FILTRO_ETIQUETA = vals[0] || null; cargarListaNotas(); }
    });
}

function abrirEditorNota(nota) {
  const ed = document.getElementById('notas-editor');
  if (!ed) return;
  ed.style.display = '';
  document.getElementById('nota-id').value = nota?.id || '';
  document.getElementById('nota-titulo').value = nota?.titulo || '';
  document.getElementById('nota-cuerpo').value = nota?.cuerpo || '';
  document.getElementById('nota-etiquetas').value = (nota?.etiquetas || []).join(', ');
  document.getElementById('nota-me-cuesta').checked = !!nota?.me_cuesta;
  document.getElementById('nota-err').textContent = '';
  document.getElementById('nota-titulo').focus();
}

function cerrarEditorNota() {
  const ed = document.getElementById('notas-editor');
  if (ed) ed.style.display = 'none';
}

async function guardarNotaDesdeEditor() {
  const err = document.getElementById('nota-err'); err.textContent = '';
  const titulo = document.getElementById('nota-titulo').value.trim();
  const cuerpo = document.getElementById('nota-cuerpo').value.trim();
  if (!titulo) { err.textContent = 'Ponele un título.'; return; }
  if (!cuerpo) { err.textContent = 'Escribí el contenido de la nota.'; return; }
  const etiquetas = document.getElementById('nota-etiquetas').value.split(',').map(e => e.trim()).filter(Boolean);
  if (etiquetas.length > 8) { err.textContent = 'Máximo 8 etiquetas.'; return; }
  const btn = document.getElementById('nota-guardar'); btn.disabled = true;
  const { data, error } = await sb.rpc('guardar_nota', {
    p_id: document.getElementById('nota-id').value || null,
    p_titulo: titulo, p_cuerpo: cuerpo, p_etiquetas: etiquetas,
    p_me_cuesta: document.getElementById('nota-me-cuesta').checked
  });
  btn.disabled = false;
  if (error || !data?.ok) { err.textContent = error?.message || 'No se pudo guardar.'; return; }
  okToast('Nota guardada'); cerrarEditorNota(); await loadMisNotas();
}

// Puente desde otras pantallas: convierte un texto ya escrito (el aprendizaje
// del informe diario, la objeción de un cliente) en nota sin reescribirlo.
window.guardarComoNota = (titulo, cuerpo, etiquetas) => {
  activateSection('mis-notas');
  abrirEditorNota({ titulo, cuerpo, etiquetas: etiquetas || [], me_cuesta: true });
};

function actualizarBadgeNotas(n) {
  const badge = document.getElementById('nav-notas-count');
  if (!badge) return;
  badge.textContent = n;
  badge.style.display = n > 0 ? '' : 'none';
}

function setupMisNotas() {
  document.getElementById('notas-nueva')?.addEventListener('click', () => abrirEditorNota(null));
  document.getElementById('nota-cancelar')?.addEventListener('click', cerrarEditorNota);
  document.getElementById('nota-guardar')?.addEventListener('click', guardarNotaDesdeEditor);
  let t = null;
  document.getElementById('notas-buscar')?.addEventListener('input', e => {
    clearTimeout(t);
    t = setTimeout(() => { NOTAS_BUSQUEDA = e.target.value.trim(); cargarListaNotas(); }, 300);
  });
}

/* ---------- Menú: fuente única de datos (sidebar desktop + sheet "Yo" móvil) ----------
   Antes cada superficie tenía su propia lista de <a> hardcodeada en el HTML,
   duplicada y desincronizada entre sí. Ahora un solo NAV_ITEMS alimenta ambas.
   `roles` preserva LITERAL las clases nav-admin-only/nav-marketing-ok/etc. que
   ya filtraban por CSS -- ese sistema no cambia, solo cambia dónde vive cada
   <a> en el DOM. */
